// src/pos/CustomerDisplay.jsx
// ============================================================
// Customer Display — React + Firestore (+ BroadcastChannel)
// ------------------------------------------------------------
// Listens on:
//   1. BroadcastChannel("pos_customer_display")  — same-PC fast path
//   2. Firestore  CustomerDisplay/{LocationID}    — cross-device sync
//
// Location is resolved from (in order):
//   • URL query  ?locationID=1
//   • URL path   /customer-display/1
//   • AuthContext.user.LocationID (if the display runs on a
//     cashier-authenticated terminal)
//   • "default"  (single-display installs)
//
// Preserves every UI element from the original:
//   • Welcome screen (empty cart)
//   • Active sale (cart table + summary sidebar)
//   • Completed screen with total + change
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { useLocation } from "react-router-dom";
import {
  ShoppingCart,
  CreditCard,
  CheckCircle,
  Store,
} from "lucide-react";
import { doc, onSnapshot } from "firebase/firestore";

import { db } from "../firebase";
import { AuthContext } from "./SERVER/AuthContext.js";

const initialState = {
  storeName: "MY POS STORE",
  cart: [],
  subtotal: 0,
  discount: 0,
  tax: 0,
  total: 0,
  paymentAmount: 0,
  change: 0,
  status: "cart",
};

export default function CustomerDisplay() {
  const { user } = useContext(AuthContext);
  const location = useLocation();

  // ============================================================
  // RESOLVE LOCATION KEY
  // ------------------------------------------------------------
  // We need a stable identifier so multiple displays at
  // different counters don't overwrite each other.
  // ============================================================
  const displayKey = useMemo(() => {
    // 1. ?locationID=1  or  ?location=1
    const params = new URLSearchParams(location.search);
    const fromQuery =
      params.get("locationID") ||
      params.get("location")   ||
      params.get("loc");
    if (fromQuery) return String(fromQuery).trim();

    // 2. /customer-display/1
    const match = location.pathname.match(/\/customer-display\/([^/]+)/i);
    if (match) return match[1];

    // 3. AuthContext user
    const userLoc =
      user?.LocationID ??
      user?.locationID ??
      user?.location   ??
      null;
    if (userLoc != null && Number(userLoc) > 0) return String(userLoc);

    // 4. Fallback
    return "default";
  }, [location.search, location.pathname, user]);

  // ============================================================
  // SALE STATE
  // ============================================================
  const [sale, setSale] = useState(initialState);

  // Merge helper — BroadcastChannel and Firestore messages both
  // funnel through here. Whichever arrives last wins.
  const applyPayload = (payload) => {
    if (!payload || typeof payload !== "object") return;
    setSale((prev) => ({ ...prev, ...payload }));
  };

  // ============================================================
  // FIRESTORE LISTENER
  // ============================================================
  useEffect(() => {
    const ref = doc(db, "CustomerDisplay", displayKey);

    const unsubscribe = onSnapshot(
      ref,
      (snap) => {
        if (snap.exists()) {
          const data = snap.data() || {};
          applyPayload(data);
        }
      },
      (err) => {
        console.error("[CustomerDisplay] Firestore listener error:", err);
      }
    );

    return () => unsubscribe();
  }, [displayKey]);

  // ============================================================
  // BROADCASTCHANNEL LISTENER (same-browser fast path)
  // ============================================================
  useEffect(() => {
    let channel;
    try {
      channel = new BroadcastChannel("pos_customer_display");
    } catch (err) {
      console.warn("[CustomerDisplay] BroadcastChannel unavailable:", err);
      return undefined;
    }

    channel.onmessage = (event) => {
      if (event.data?.type === "POS_STATE") {
        applyPayload(event.data.payload);
      }
    };

    return () => channel.close();
  }, []);

  // ============================================================
  // MONEY FORMATTER
  // ============================================================
  const money = (value) =>
    Number(value || 0).toLocaleString("en-LK", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });

  // ============================================================
  // EMPTY / WELCOME SCREEN
  // ============================================================
  if (!sale.cart?.length && sale.status !== "completed") {
    return (
      <div className="min-h-screen bg-slate-950 text-white flex flex-col">
        <header className="h-20 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-10">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-blue-600 flex items-center justify-center">
              <Store size={26} />
            </div>

            <div>
              <h1 className="text-2xl font-bold">{sale.storeName}</h1>
              <p className="text-slate-400 text-sm">Customer Display</p>
            </div>
          </div>

          <div className="text-slate-400">
            Thank you for shopping with us
          </div>
        </header>

        <main className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <div className="w-32 h-32 mx-auto mb-8 rounded-full bg-slate-900 flex items-center justify-center">
              <ShoppingCart size={64} className="text-blue-500" />
            </div>

            <h2 className="text-5xl font-bold mb-4">Welcome!</h2>

            <p className="text-2xl text-slate-400">
              Your items will appear here
            </p>
          </div>
        </main>

        <footer className="h-16 bg-slate-900 border-t border-slate-800 flex items-center justify-center text-slate-500">
          Please wait while your cashier processes your order
        </footer>
      </div>
    );
  }

  // ============================================================
  // SALE COMPLETED
  // ============================================================
  if (sale.status === "completed") {
    return (
      <div className="min-h-screen bg-slate-950 text-white flex items-center justify-center">
        <div className="text-center">
          <div className="w-32 h-32 mx-auto rounded-full bg-green-500/20 flex items-center justify-center mb-8">
            <CheckCircle size={80} className="text-green-500" />
          </div>

          <h1 className="text-6xl font-bold mb-5">Thank You!</h1>

          <p className="text-3xl text-slate-300 mb-10">
            Your payment was successful
          </p>

          <div className="bg-slate-900 rounded-2xl p-8 min-w-[420px]">
            <div className="text-slate-400 text-lg">Total</div>

            <div className="text-5xl font-bold mt-2">
              Rs. {money(sale.total)}
            </div>

            {Number(sale.change) > 0 && (
              <div className="mt-6">
                <div className="text-slate-400">Change</div>

                <div className="text-3xl font-bold text-green-400">
                  Rs. {money(sale.change)}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // ============================================================
  // ACTIVE SALE
  // ============================================================
  return (
    <div className="min-h-screen bg-slate-950 text-white flex flex-col">
      {/* HEADER */}
      <header className="h-20 bg-slate-900 border-b border-slate-800 px-8 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center">
            <Store size={26} />
          </div>

          <div>
            <h1 className="text-2xl font-bold">{sale.storeName}</h1>
            <p className="text-sm text-slate-400">Your Order</p>
          </div>
        </div>

        <div className="flex items-center gap-3 text-slate-400">
          <ShoppingCart size={22} />
          <span>
            {sale.cart.length} item{sale.cart.length !== 1 ? "s" : ""}
          </span>
        </div>
      </header>

      {/* CONTENT */}
      <main className="flex-1 grid grid-cols-1 lg:grid-cols-[1fr_420px] gap-6 p-6">
        {/* CART */}
        <section className="bg-slate-900 rounded-2xl overflow-hidden border border-slate-800">
          <div className="px-6 py-5 border-b border-slate-800">
            <h2 className="text-xl font-semibold">Order Details</h2>
          </div>

          <div className="divide-y divide-slate-800">
            {sale.cart.map((item, index) => {
              const quantity = Number(item.qty ?? item.quantity ?? 0);
              const price    = Number(item.price ?? item.sellingPrice ?? 0);
              const amount   = Number(item.amount ?? quantity * price);

              return (
                <div
                  key={item.productCode || item.ProductCode || index}
                  className="px-6 py-5 flex items-center justify-between"
                >
                  <div className="flex-1">
                    <div className="text-lg font-semibold">
                      {item.productName || item.ProductName || "Product"}
                    </div>
                    <div className="text-sm text-slate-400 mt-1">
                      {item.productCode || item.ProductCode || ""}
                    </div>
                  </div>

                  <div className="w-24 text-center">
                    <div className="text-slate-400 text-sm">Qty</div>
                    <div className="text-xl font-semibold">{quantity}</div>
                  </div>

                  <div className="w-32 text-right">
                    <div className="text-slate-400 text-sm">Price</div>
                    <div>Rs. {money(price)}</div>
                  </div>

                  <div className="w-36 text-right">
                    <div className="text-slate-400 text-sm">Amount</div>
                    <div className="text-xl font-semibold">
                      Rs. {money(amount)}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* SUMMARY */}
        <aside className="bg-slate-900 rounded-2xl border border-slate-800 p-7 flex flex-col">
          <h2 className="text-xl font-semibold mb-8">Order Summary</h2>

          <div className="space-y-5">
            <div className="flex justify-between text-lg">
              <span className="text-slate-400">Subtotal</span>
              <span>Rs. {money(sale.subtotal)}</span>
            </div>

            {Number(sale.discount) > 0 && (
              <div className="flex justify-between text-lg">
                <span className="text-slate-400">Discount</span>
                <span className="text-green-400">
                  - Rs. {money(sale.discount)}
                </span>
              </div>
            )}

            {Number(sale.tax) > 0 && (
              <div className="flex justify-between text-lg">
                <span className="text-slate-400">Tax</span>
                <span>Rs. {money(sale.tax)}</span>
              </div>
            )}
          </div>

          <div className="border-t border-slate-700 my-8" />

          <div>
            <div className="text-slate-400 text-lg">Total</div>
            <div className="text-5xl font-bold mt-2">
              Rs. {money(sale.total)}
            </div>
          </div>

          {Number(sale.paymentAmount) > 0 && (
            <div className="mt-auto pt-8 space-y-4">
              <div className="flex justify-between">
                <span className="text-slate-400">Payment</span>
                <span className="font-semibold">
                  Rs. {money(sale.paymentAmount)}
                </span>
              </div>

              {Number(sale.change) > 0 && (
                <div className="flex justify-between text-xl">
                  <span className="text-slate-400">Change</span>
                  <span className="font-bold text-green-400">
                    Rs. {money(sale.change)}
                  </span>
                </div>
              )}
            </div>
          )}
        </aside>
      </main>

      <footer className="h-16 bg-slate-900 border-t border-slate-800 flex items-center justify-center">
        <div className="flex items-center gap-3 text-slate-400">
          <CreditCard size={20} />
          <span>Please check your order before payment</span>
        </div>
      </footer>
    </div>
  );
}