// Salesreport.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - Sales      (one doc per invoice; embeds itemsList[])
//   - Locations  (via COLLECTIONS.LOCATIONS)
//
// Load pattern:
//   Load ALL Sales with IsDelete == 0, then filter by Location
//   and date client-side. This avoids Firestore's strict type
//   matching on LocationID (string vs number) and lets the
//   datetime-local inputs work without a composite index.
//
//   If the collection grows large, swap the load for:
//     listCollection(SALES, { where: [["LocationID", "==", Number(id)], ["IsDelete", "==", 0]] })
//   and keep the date filter client-side.
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import { COLLECTIONS, listCollection } from "../lib/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS
====================================================== */

const SALES = COLLECTIONS?.SALES ?? "Sales";

/* ======================================================
   HELPERS
====================================================== */

const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

// Convert any Firestore-ish date (Timestamp, Date, ISO string,
// { seconds, nanoseconds }, ms number) to milliseconds.
const toMillis = (value) => {
  if (value === null || value === undefined) return 0;

  if (typeof value === "number") return value;

  if (value instanceof Date) return value.getTime();

  if (typeof value === "string") {
    const t = new Date(value).getTime();
    return Number.isFinite(t) ? t : 0;
  }

  if (typeof value.toDate === "function") {
    return value.toDate().getTime();
  }

  if (typeof value.seconds === "number") {
    return value.seconds * 1000;
  }

  const t = new Date(value).getTime();
  return Number.isFinite(t) ? t : 0;
};

/* ======================================================
   NORMALIZERS
====================================================== */

const normalizeLocation = (raw) => ({
  ...raw,
  LocationID:
    raw.LocationID ?? raw.locationID ?? raw.id ?? "",
  LocationCode:
    pick(raw, "LocationCode", "locationCode", "locationcode") || "",
  LocationName:
    pick(raw, "LocationName", "locationName", "locationname") ||
    pick(raw, "Location", "location", "Name", "name") ||
    "",
});

/* ======================================================
   COMPONENT
====================================================== */

export default function Salesreport() {
  const { user } = useContext(AuthContext);

  const [isOpen, setIsOpen] = useState(false);
  const [locations, setLocations] = useState([]);

  const [selectedLocation, setSelectedLocation] = useState({
    LocationID: "",
    LocationCode: "",
    LocationName: "",
  });

  const [fromdate, setFromDate] = useState("");
  const [todate, setToDate] = useState("");

  const [invoice, setInvoice] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  /* ======================================================
     F12 SHORTCUT — open location modal
  ====================================================== */

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "F12") {
        event.preventDefault();
        setIsOpen(true);
        loadLocations();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ======================================================
     LOAD LOCATIONS  (Firestore)
  ====================================================== */

  const loadLocations = useCallback(async () => {
    try {
      setError("");

      const rows = await listCollection(COLLECTIONS.LOCATIONS, {
        where: [["IsDelete", "==", 0]],
      });

      setLocations(rows.map(normalizeLocation));
    } catch (err) {
      console.error("LOCATION LOAD ERROR:", err);
      setError(
        err.message || "Failed to load locations."
      );
    }
  }, []);

  /* ======================================================
     SEARCH SALES REPORT
  ====================================================== */

  const searchSalesReport = async (e) => {
    e.preventDefault();

    if (!selectedLocation.LocationID) {
      setError("Please select a location.");
      return;
    }

    if (!fromdate || !todate) {
      setError("Please select From Date and To Date.");
      return;
    }

    const fromMs = new Date(fromdate).getTime();
    const toMs = new Date(todate).getTime();

    if (!Number.isFinite(fromMs) || !Number.isFinite(toMs)) {
      setError("Invalid date range.");
      return;
    }

    if (fromMs > toMs) {
      setError("From Date must be before To Date.");
      return;
    }

    try {
      setLoading(true);
      setError("");
      setInvoice([]);

      /* ---- 1. Load Sales (IsDelete == 0) ---- */

      const salesRows = await listCollection(SALES, {
        where: [["IsDelete", "==", 0]],
      });

      /* ---- 2. Filter by location ---- */

      const locationMatches = salesRows.filter((sale) => {
        const sid = String(
          pick(sale, "LocationID", "locationID", "locationid") ?? ""
        );
        return sid === String(selectedLocation.LocationID);
      });

      /* ---- 3. Filter by date range ---- */

      const dateMatches = locationMatches.filter((sale) => {
        const saleDate =
          sale.RecDate ??
          sale.recDate ??
          sale.InvoiceDate ??
          sale.CreatedAt;

        const ms = toMillis(saleDate);

        return ms >= fromMs && ms <= toMs;
      });

      /* ---- 4. Flatten itemsList into rows ---- */

      const rows = [];

      dateMatches.forEach((sale) => {
        const receipt = pick(
          sale,
          "Receipt",
          "receipt",
          "InvoiceNumber"
        );

        const locId = pick(
          sale,
          "LocationID",
          "locationID",
          "locationid"
        );

        const items = Array.isArray(sale.itemsList)
          ? sale.itemsList
          : Array.isArray(sale.items)
            ? sale.items
            : [];

        items.forEach((item) => {
          rows.push({
            Receipt: String(receipt || ""),
            ProductCode: pick(
              item,
              "ProductCode",
              "productcode",
              "ItemCode"
            ),
            Descrip:
              pick(
                item,
                "Descrip",
                "ProductName",
                "ItemName"
              ) || "",
            Qty: toNumber(pick(item, "Qty", "Quantity")),
            Cost: toNumber(
              pick(item, "Cost", "CostPrice", "UnitCost")
            ),
            Price: toNumber(
              pick(item, "Price", "UnitPrice", "SellingPrice")
            ),
            FixedDiscount: toNumber(
              pick(
                item,
                "FixedDiscount",
                "DiscountAmount",
                "Discount"
              )
            ),
            LocationID: String(locId ?? ""),
          });
        });
      });

      setInvoice(rows);
    } catch (err) {
      console.error("SALES REPORT ERROR:", err);
      setError(
        err.message || "Failed to load sales report."
      );
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     DERIVED
  ====================================================== */

  const totalQty = useMemo(
    () => invoice.reduce((sum, r) => sum + r.Qty, 0),
    [invoice]
  );

  const totalNet = useMemo(
    () =>
      invoice.reduce(
        (sum, r) => sum + r.Qty * r.Price - r.FixedDiscount,
        0
      ),
    [invoice]
  );

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="w-full mx-auto mt-10 p-4">
      <div className="mb-4">
        {user?.username
          ? `Welcome, ${user.username}`
          : "No user logged in"}
      </div>

      {/* SEARCH FORM */}

      <div className="mt-6 p-4 bg-white border border-gray-100 rounded-2xl shadow-sm">
        <form onSubmit={searchSalesReport} className="space-y-4">
          <div className="grid grid-cols-6 gap-4 items-center">
            <h3>Location</h3>

            <input
              type="text"
              name="location"
              placeholder="Location"
              value={selectedLocation.LocationID}
              readOnly
              onClick={() => {
                setIsOpen(true);
                loadLocations();
              }}
              title={
                selectedLocation.LocationName
                  ? `${selectedLocation.LocationCode || ""} - ${selectedLocation.LocationName}`.trim()
                  : ""
              }
              className="w-full border p-2 rounded cursor-pointer"
              required
            />

            <h3>From Date</h3>

            <input
              type="datetime-local"
              value={fromdate}
              onChange={(e) => setFromDate(e.target.value)}
              className="w-full border p-2 rounded"
              required
            />

            <h3>To Date</h3>

            <input
              type="datetime-local"
              value={todate}
              onChange={(e) => setToDate(e.target.value)}
              className="w-full border p-2 rounded"
              required
            />

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500 disabled:bg-gray-400"
            >
              {loading ? "Searching..." : "Search"}
            </button>
          </div>
        </form>

        {error && (
          <div className="mt-4 text-red-600">{error}</div>
        )}
      </div>

      {/* SALES REPORT TABLE */}

      <div className="w-full overflow-hidden rounded-lg shadow-lg border border-gray-200 bg-white mt-4">
        <div className="overflow-x-auto">
          <table className="w-full border-collapse text-left text-sm text-gray-700">
            <thead className="bg-gray-50 text-gray-800">
              <tr>
                <th className="px-6 py-4 font-medium">Inv No</th>
                <th className="px-6 py-4 font-medium">
                  Product Code
                </th>
                <th className="px-6 py-4 font-medium">
                  Product Name
                </th>
                <th className="px-6 py-4 font-medium">Quantity</th>
                <th className="px-6 py-4 font-medium">
                  Cost Price
                </th>
                <th className="px-6 py-4 font-medium">
                  Selling Price
                </th>
                <th className="px-6 py-4 font-medium">Discount</th>
                <th className="px-6 py-4 font-medium">Location</th>
              </tr>
            </thead>

            <tbody className="divide-y divide-gray-100 border-t border-gray-100">
              {loading ? (
                <tr>
                  <td
                    colSpan="8"
                    className="px-6 py-8 text-center text-gray-500"
                  >
                    Loading…
                  </td>
                </tr>
              ) : invoice.length === 0 ? (
                <tr>
                  <td
                    colSpan="8"
                    className="px-6 py-8 text-center text-gray-500"
                  >
                    No sales found.
                  </td>
                </tr>
              ) : (
                invoice.map((row, index) => (
                  <tr
                    key={`${row.Receipt}-${row.ProductCode}-${index}`}
                    className="hover:bg-gray-50"
                  >
                    <td className="px-6 py-4 font-medium text-gray-900">
                      {row.Receipt}
                    </td>
                    <td className="px-6 py-4">
                      {row.ProductCode}
                    </td>
                    <td className="px-6 py-4">{row.Descrip}</td>
                    <td className="px-6 py-4">{row.Qty}</td>
                    <td className="px-6 py-4">
                      {row.Cost.toFixed(2)}
                    </td>
                    <td className="px-6 py-4">
                      {row.Price.toFixed(2)}
                    </td>
                    <td className="px-6 py-4 text-red-600">
                      {row.FixedDiscount.toFixed(2)}
                    </td>
                    <td className="px-6 py-4">
                      {row.LocationID}
                    </td>
                  </tr>
                ))
              )}
            </tbody>

            {invoice.length > 0 && (
              <tfoot className="bg-gray-50 font-semibold text-gray-800">
                <tr>
                  <td
                    colSpan="3"
                    className="px-6 py-3 text-right"
                  >
                    Total
                  </td>
                  <td className="px-6 py-3">
                    {totalQty.toFixed(3)}
                  </td>
                  <td className="px-6 py-3">—</td>
                  <td className="px-6 py-3">—</td>
                  <td className="px-6 py-3 text-red-600">
                    {invoice
                      .reduce(
                        (s, r) => s + r.FixedDiscount,
                        0
                      )
                      .toFixed(2)}
                  </td>
                  <td className="px-6 py-3">
                    Net: {totalNet.toFixed(2)}
                  </td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </div>

      {/* LOCATION MODAL */}

      {isOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-[600px] max-w-[90%] relative">
            <button
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

            <h2 className="text-lg font-semibold mb-4">
              Select Location
            </h2>

            <div className="overflow-x-auto rounded-lg border border-gray-200">
              <table className="min-w-full bg-white">
                <thead className="bg-gray-100">
                  <tr>
                    <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">
                      Location Code
                    </th>
                    <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">
                      Location Name
                    </th>
                  </tr>
                </thead>

                <tbody className="divide-y divide-gray-200">
                  {locations.length === 0 ? (
                    <tr>
                      <td
                        colSpan="2"
                        className="px-6 py-6 text-center text-gray-500"
                      >
                        No locations found.
                      </td>
                    </tr>
                  ) : (
                    locations.map((item, index) => (
                      <tr
                        key={item.LocationID || index}
                        className="hover:bg-gray-50 cursor-pointer"
                        onClick={() => {
                          setSelectedLocation(item);
                          setIsOpen(false);
                        }}
                      >
                        <td className="px-6 py-4">
                          {item.LocationCode ||
                            item.LocationID}
                        </td>
                        <td className="px-6 py-4">
                          {item.LocationName}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>

            <button
              onClick={() => setIsOpen(false)}
              className="mt-4 bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}