// Stadjust.jsx — Firestore version
import React, { useCallback, useContext, useEffect, useMemo, useState } from "react";
import {
  Check, ChevronDown, ClipboardList, Loader2, Package, Plus,
  RefreshCw, Search, Trash2, X,
} from "lucide-react";
import { doc, collection, updateDoc, deleteDoc, serverTimestamp } from "firebase/firestore";
import { db } from "../firebase.js";
import { COLLECTIONS, listCollection, createDoc } from "../lib/firestore";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

const SESSIONS = COLLECTIONS?.STOCK_COUNT_SESSIONS ?? "StockCountSessions";
const PRODUCTS = COLLECTIONS?.PRODUCTS ?? "Products";
const PRODUCT_STOCK = COLLECTIONS?.PRODUCT_STOCK ?? "ProductStock";

const pick = (o, ...ks) => { for (const k of ks) if (o?.[k] != null) return o[k]; return ""; };
const toNum = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const todayString = () => new Date().toISOString().slice(0, 10);

function StockCount() {
  const { user } = useContext(AuthContext);
  const username = useMemo(() => user?.username || user?.Username || user?.U || "", [user]);
  const companyID = useMemo(() => user?.companyID ?? user?.CompanyID ?? "", [user]);
  const locationID = useMemo(() => user?.locationID ?? user?.LocationID ?? "", [user]);

  const [department, setDepartment] = useState("");
  const [category, setCategory] = useState("");
  const [supplier, setSupplier] = useState("");
  const [basket, setBasket] = useState("");
  const [productSearch, setProductSearch] = useState("");
  const [departments, setDepartments] = useState([]);
  const [categories, setCategories] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [baskets, setBaskets] = useState([]);
  const [products, setProducts] = useState([]);
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [session, setSession] = useState(null);
  const [sessionItems, setSessionItems] = useState([]);
  const [sessionRemark, setSessionRemark] = useState("");
  const [loadingFilters, setLoadingFilters] = useState(false);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [startingSession, setStartingSession] = useState(false);
  const [saving, setSaving] = useState(false);
  const [finishing, setFinishing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const loadFilters = useCallback(async () => {
    try {
      setLoadingFilters(true); setError("");
      const rows = await listCollection(PRODUCTS, { where: [["IsDelete", "==", 0]] });
      const deptSet = new Set(), catSet = new Set(), supSet = new Set(), baskSet = new Set();
      rows.forEach((p) => {
        const d = pick(p, "Department", "DepartmentName"); if (d) deptSet.add(d);
        const c = pick(p, "Category", "CategoryName"); if (c) catSet.add(c);
        const s = pick(p, "Supplier", "SupplierName"); if (s) supSet.add(s);
        const b = pick(p, "Basket", "BasketName"); if (b) baskSet.add(b);
      });
      setDepartments([...deptSet].sort());
      setCategories([...catSet].sort());
      setSuppliers([...supSet].sort());
      setBaskets([...baskSet].sort());
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to load filters.");
    } finally { setLoadingFilters(false); }
  }, []);

  useEffect(() => { loadFilters(); }, [loadFilters]);

  const searchProducts = async () => {
    try {
      setLoadingProducts(true); setError(""); setSuccess("");
      const rows = await listCollection(PRODUCTS, { where: [["IsDelete", "==", 0]] });
      const q = productSearch.trim().toLowerCase();
      const filtered = rows.filter((p) => {
        if (department && String(pick(p, "Department", "DepartmentName")) !== department) return false;
        if (category && String(pick(p, "Category", "CategoryName")) !== category) return false;
        if (supplier && String(pick(p, "Supplier", "SupplierName")) !== supplier) return false;
        if (basket && String(pick(p, "Basket", "BasketName")) !== basket) return false;
        if (q) {
          const code = String(pick(p, "ProductCode", "productcode")).toLowerCase();
          const name = String(pick(p, "ProductName", "productname")).toLowerCase();
          if (!code.includes(q) && !name.includes(q)) return false;
        }
        return true;
      });
      setProducts(filtered.map((r) => ({
        ...r,
        InvProductMasterID: r.id,
        ProductCode: pick(r, "ProductCode", "productcode"),
        ProductName: pick(r, "ProductName", "productname"),
        Department: pick(r, "Department", "DepartmentName"),
        Category: pick(r, "Category", "CategoryName"),
        Supplier: pick(r, "Supplier", "SupplierName"),
        SystemStock: toNum(pick(r, "Stock", "CurrentStock")),
      })));
    } catch (err) {
      console.error(err);
      setProducts([]);
      setError(err.message || "Unable to load products.");
    } finally { setLoadingProducts(false); }
  };

  const getProductID = (product) => product.InvProductMasterID ?? product.ProductID ?? null;
  const isSelected = (product) => selectedProducts.some((p) => Number(getProductID(p)) === Number(getProductID(product)));
  const toggleProduct = (product) => {
    const id = getProductID(product);
    if (!id) return;
    if (isSelected(product)) setSelectedProducts((prev) => prev.filter((p) => Number(getProductID(p)) !== Number(id)));
    else setSelectedProducts((prev) => [...prev, product]);
  };

  const allProductsSelected = products.length > 0 && products.every((p) => isSelected(p));
  const toggleSelectAll = () => {
    if (allProductsSelected) {
      const ids = new Set(products.map((p) => Number(getProductID(p))));
      setSelectedProducts((prev) => prev.filter((p) => !ids.has(Number(getProductID(p)))));
    } else {
      setSelectedProducts((prev) => {
        const existing = new Set(prev.map((p) => Number(getProductID(p))));
        const adds = products.filter((p) => !existing.has(Number(getProductID(p))));
        return [...prev, ...adds];
      });
    }
  };

  const startSession = async () => {
    try {
      setError(""); setSuccess("");
      if (!username) { setError("Username is not available."); return; }
      if (!locationID) { setError("Location is not available."); return; }
      if (selectedProducts.length === 0) { setError("Please select at least one product."); return; }

      setStartingSession(true);

      // Generate session no
      const existing = await listCollection(SESSIONS);
      let max = 0;
      existing.forEach((r) => {
        const m = String(pick(r, "SessionNo", "sessionNo") || "").match(/(\d+)$/);
        if (m) { const n = Number(m[1]); if (n > max) max = n; }
      });
      const sessionNo = `SC${String(max + 1).padStart(5, "0")}`;

      // Snapshot system stock for selected products
      const stockRows = await listCollection(PRODUCT_STOCK, {
        where: [["LocationID", "==", Number(locationID)], ["IsDelete", "==", 0]],
      });
      const stockMap = {};
      stockRows.forEach((s) => { const c = pick(s, "ProductCode", "productcode"); if (c) stockMap[c] = toNum(pick(s, "Stock", "CurrentStock")); });

      const items = selectedProducts.map((p, idx) => ({
        LineNo: idx + 1,
        ProductCode: p.ProductCode,
        ProductName: p.ProductName,
        SystemStock: stockMap[p.ProductCode] ?? p.SystemStock ?? 0,
        StoreCount: null,
        RackCount: null,
      }));

      const ref = await createDoc(SESSIONS, {
        SessionNo: sessionNo,
        Username: username,
        CompanyID: Number(companyID) || 0,
        LocationID: Number(locationID),
        Status: "Open",
        StartedAt: serverTimestamp(),
        CreatedBy: username,
        IsDelete: 0,
        Department: department || null,
        Category: category || null,
        Supplier: supplier || null,
        Basket: basket || null,
        items,
      }, { username });

      setSession({ SessionNo: sessionNo, StockCountSessionID: ref.id, Status: "Open", LocationID: Number(locationID) });
      setSessionItems(
        items.map((it, idx) => ({
          ...it,
          StockCountSessionDetID: `${ref.id}-${idx}`,
          StoreCount: "",
          RackCount: "",
        }))
      );
      setSuccess(`Stock count session ${sessionNo} started.`);
      setSelectedProducts([]); setProducts([]);
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to start stock count.");
    } finally { setStartingSession(false); }
  };

  const updateCount = (detailID, field, value) => {
    setSessionItems((prev) => prev.map((it) => String(it.StockCountSessionDetID) === String(detailID) ? { ...it, [field]: value } : it));
  };

  const getStoreCount = (it) => { const v = Number(it.StoreCount); return Number.isFinite(v) ? v : 0; };
  const getRackCount = (it) => { const v = Number(it.RackCount); return Number.isFinite(v) ? v : 0; };
  const getSystemStock = (it) => toNum(it.SystemStock);
  const getPhysicalTotal = (it) => getStoreCount(it) + getRackCount(it);
  const getVariance = (it) => getPhysicalTotal(it) - getSystemStock(it);

  const saveSession = async () => {
    try {
      setError(""); setSuccess("");
      if (!session?.StockCountSessionID) { setError("No active session."); return; }
      setSaving(true);

      await updateDoc(doc(db, SESSIONS, session.StockCountSessionID), {
        items: sessionItems.map((it) => ({
          LineNo: it.LineNo, ProductCode: it.ProductCode, ProductName: it.ProductName,
          SystemStock: it.SystemStock, StoreCount: it.StoreCount ?? null, RackCount: it.RackCount ?? null,
        })),
        UpdatedAt: serverTimestamp(),
        UpdatedBy: username,
      });

      setSuccess("Stock count saved successfully.");
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to save stock count.");
    } finally { setSaving(false); }
  };

  const finishSession = async () => {
    try {
      setError(""); setSuccess("");
      if (!session?.StockCountSessionID) { setError("No active session."); return; }
      const incomplete = sessionItems.filter((it) => it.StoreCount === "" || it.StoreCount == null || it.RackCount === "" || it.RackCount == null);
      if (incomplete.length > 0) { setError(`${incomplete.length} item(s) incomplete.`); return; }

      setFinishing(true);
      await updateDoc(doc(db, SESSIONS, session.StockCountSessionID), {
        items: sessionItems.map((it) => ({
          LineNo: it.LineNo, ProductCode: it.ProductCode, ProductName: it.ProductName,
          SystemStock: it.SystemStock, StoreCount: Number(it.StoreCount), RackCount: Number(it.RackCount),
        })),
        Status: "Finished",
        FinishedAt: serverTimestamp(),
        Remark: sessionRemark.trim() || null,
        UpdatedBy: username,
      });
      setSession((p) => ({ ...p, Status: "Finished" }));
      setSuccess("Stock count finished and sent for approval.");
      setSessionRemark("");
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to finish stock count.");
    } finally { setFinishing(false); }
  };

  const deleteSession = async () => {
    try {
      setError(""); setSuccess("");
      if (!session?.StockCountSessionID) { setError("No active session."); return; }
      if (!window.confirm(`Delete session ${session.SessionNo}?`)) return;
      setDeleting(true);
      await deleteDoc(doc(db, SESSIONS, session.StockCountSessionID));
      setSession(null); setSessionItems([]); setSessionRemark("");
      setSuccess("Session deleted.");
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to delete session.");
    } finally { setDeleting(false); }
  };

  const clearSearch = () => {
    setDepartment(""); setCategory(""); setSupplier(""); setBasket(""); setProductSearch("");
    setProducts([]); setSelectedProducts([]); setError(""); setSuccess("");
  };

  const sessionTotals = useMemo(() => {
    let total = sessionItems.length, completed = 0, missing = 0, variance = 0;
    sessionItems.forEach((it) => {
      const s = it.StoreCount != null && it.StoreCount !== "";
      const r = it.RackCount != null && it.RackCount !== "";
      if (s && r) completed++; else missing++;
      variance += getVariance(it);
    });
    return { total, completed, missing, variance };
  }, [sessionItems]);

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-blue-600 p-3 text-white"><ClipboardList size={25} /></div>
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Stock Count</h1>
              <p className="text-sm text-gray-500">Count physical stock by location</p>
            </div>
          </div>
          <button type="button" onClick={loadFilters} disabled={loadingFilters}
            className="inline-flex items-center justify-center gap-2 rounded-lg border bg-white px-4 py-2 text-sm font-medium text-gray-700 shadow-sm hover:bg-gray-50 disabled:opacity-50">
            <RefreshCw size={17} className={loadingFilters ? "animate-spin" : ""} /> Refresh
          </button>
        </div>

        {error && <div className="mb-4 flex items-start gap-3 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700"><X size={18} className="mt-0.5 shrink-0" /><div className="flex-1">{error}</div><button onClick={() => setError("")}><X size={16} /></button></div>}
        {success && <div className="mb-4 flex items-start gap-3 rounded-lg border border-green-200 bg-green-50 p-4 text-sm text-green-700"><Check size={18} className="mt-0.5 shrink-0" /><div>{success}</div></div>}

        <div className="mb-6 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div className="rounded-xl border bg-white p-4 shadow-sm">
            <div className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500">User</div>
            <div className="font-semibold text-gray-800">{username || "Not available"}</div>
          </div>
          <div className="rounded-xl border bg-white p-4 shadow-sm">
            <div className="mb-1 text-xs font-medium uppercase tracking-wide text-gray-500">Company</div>
            <div className="font-semibold text-gray-800">{companyID || "Not available"}</div>
          </div>
          <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 shadow-sm">
            <div className="mb-1 text-xs font-medium uppercase tracking-wide text-blue-600">Counting Location</div>
            <div className="font-semibold text-blue-900">{locationID || "Not available"}</div>
          </div>
        </div>

        {session && (
          <div className="mb-6 rounded-xl border bg-white shadow-sm">
            <div className="border-b p-4">
              <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                <div>
                  <div className="flex flex-wrap items-center gap-3">
                    <h2 className="text-lg font-bold text-gray-800">Active Session</h2>
                    <span className="rounded-full bg-blue-100 px-3 py-1 text-xs font-semibold text-blue-700">{session.SessionNo}</span>
                    <span className="rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700">{session.Status || "Open"}</span>
                  </div>
                </div>
                <div className="flex flex-wrap gap-2">
                  <button type="button" onClick={saveSession} disabled={saving || finishing || session.Status !== "Open"}
                    className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50">
                    {saving ? <Loader2 size={17} className="animate-spin" /> : <Check size={17} />} Save
                  </button>
                  <button type="button" onClick={finishSession} disabled={saving || finishing || session.Status !== "Open"}
                    className="inline-flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-semibold text-white hover:bg-green-700 disabled:opacity-50">
                    {finishing ? <Loader2 size={17} className="animate-spin" /> : <Check size={17} />} Finish Session
                  </button>
                  <button type="button" onClick={deleteSession} disabled={deleting || saving || finishing || session.Status !== "Open"}
                    className="inline-flex items-center gap-2 rounded-lg border border-red-200 bg-white px-4 py-2 text-sm font-semibold text-red-600 hover:bg-red-50 disabled:opacity-50">
                    {deleting ? <Loader2 size={17} className="animate-spin" /> : <Trash2 size={17} />} Delete
                  </button>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3 border-b p-4 md:grid-cols-4">
              <div className="rounded-lg bg-gray-50 p-3"><div className="text-xs text-gray-500">Total Items</div><div className="mt-1 text-xl font-bold text-gray-800">{sessionTotals.total}</div></div>
              <div className="rounded-lg bg-green-50 p-3"><div className="text-xs text-green-600">Completed</div><div className="mt-1 text-xl font-bold text-green-700">{sessionTotals.completed}</div></div>
              <div className="rounded-lg bg-orange-50 p-3"><div className="text-xs text-orange-600">Missing</div><div className="mt-1 text-xl font-bold text-orange-700">{sessionTotals.missing}</div></div>
              <div className="rounded-lg bg-blue-50 p-3"><div className="text-xs text-blue-600">Total Variance</div><div className="mt-1 text-xl font-bold text-blue-700">{sessionTotals.variance.toFixed(2)}</div></div>
            </div>

            <div className="border-b p-4">
              <label className="mb-2 block text-sm font-medium text-gray-700">Remark</label>
              <input type="text" value={sessionRemark} onChange={(e) => setSessionRemark(e.target.value)} disabled={session.Status !== "Open"}
                placeholder="Optional remark before finishing..."
                className="w-full rounded-lg border px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100" />
            </div>

            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">#</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">Product Code</th>
                    <th className="whitespace-nowrap px-4 py-3 text-left font-semibold text-gray-600">Product Name</th>
                    <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">System Stock</th>
                    <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">Store Count</th>
                    <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">Rack Count</th>
                    <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">Physical Total</th>
                    <th className="whitespace-nowrap px-4 py-3 text-right font-semibold text-gray-600">Variance</th>
                    <th className="whitespace-nowrap px-4 py-3 text-center font-semibold text-gray-600">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {sessionItems.length === 0 ? (
                    <tr><td colSpan="9" className="px-4 py-10 text-center text-gray-500">No products in this session.</td></tr>
                  ) : sessionItems.map((item, index) => {
                    const variance = getVariance(item);
                    const completed = item.StoreCount != null && item.StoreCount !== "" && item.RackCount != null && item.RackCount !== "";
                    return (
                      <tr key={item.StockCountSessionDetID} className="hover:bg-gray-50">
                        <td className="px-4 py-3 text-gray-500">{index + 1}</td>
                        <td className="px-4 py-3 font-medium text-gray-800">{item.ProductCode || "-"}</td>
                        <td className="px-4 py-3 text-gray-700">{item.ProductName || "-"}</td>
                        <td className="px-4 py-3 text-right font-medium text-gray-700">{getSystemStock(item).toFixed(2)}</td>
                        <td className="px-4 py-3">
                          <input type="number" min="0" step="0.01" value={item.StoreCount ?? ""} disabled={session.Status !== "Open"}
                            onChange={(e) => updateCount(item.StockCountSessionDetID, "StoreCount", e.target.value)}
                            className="w-28 rounded-lg border px-3 py-2 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100" />
                        </td>
                        <td className="px-4 py-3">
                          <input type="number" min="0" step="0.01" value={item.RackCount ?? ""} disabled={session.Status !== "Open"}
                            onChange={(e) => updateCount(item.StockCountSessionDetID, "RackCount", e.target.value)}
                            className="w-28 rounded-lg border px-3 py-2 text-right outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-100" />
                        </td>
                        <td className="px-4 py-3 text-right font-semibold text-gray-800">{getPhysicalTotal(item).toFixed(2)}</td>
                        <td className={`px-4 py-3 text-right font-bold ${variance < 0 ? "text-red-600" : variance > 0 ? "text-green-600" : "text-gray-600"}`}>
                          {variance > 0 ? "+" : ""}{variance.toFixed(2)}
                        </td>
                        <td className="px-4 py-3 text-center">
                          {completed ? (
                            <span className="inline-flex items-center gap-1 rounded-full bg-green-100 px-3 py-1 text-xs font-semibold text-green-700"><Check size={13} />Completed</span>
                          ) : (
                            <span className="rounded-full bg-orange-100 px-3 py-1 text-xs font-semibold text-orange-700">Missing</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {!session && (
          <div className="rounded-xl border bg-white shadow-sm">
            <div className="border-b p-5">
              <div className="flex items-center gap-3">
                <div className="rounded-lg bg-blue-100 p-2 text-blue-600"><Plus size={20} /></div>
                <div>
                  <h2 className="text-lg font-bold text-gray-800">Start Stock Count</h2>
                  <p className="text-sm text-gray-500">Select products to include in the stock count.</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-4 p-5 md:grid-cols-2 lg:grid-cols-4">
              {[
                { label: "Department", value: department, setter: setDepartment, options: departments, all: "All Departments" },
                { label: "Category", value: category, setter: setCategory, options: categories, all: "All Categories" },
                { label: "Supplier", value: supplier, setter: setSupplier, options: suppliers, all: "All Suppliers" },
                { label: "Basket", value: basket, setter: setBasket, options: baskets, all: "All Baskets" },
              ].map((f) => (
                <div key={f.label}>
                  <label className="mb-1 block text-sm font-medium text-gray-700">{f.label}</label>
                  <div className="relative">
                    <select value={f.value} onChange={(e) => f.setter(e.target.value)}
                      className="w-full appearance-none rounded-lg border bg-white px-3 py-2.5 pr-9 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100">
                      <option value="">{f.all}</option>
                      {f.options.map((o, i) => <option key={`${o}-${i}`} value={o}>{o}</option>)}
                    </select>
                    <ChevronDown size={17} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  </div>
                </div>
              ))}
            </div>

            <div className="flex flex-col gap-3 border-y bg-gray-50 p-5 md:flex-row">
              <div className="relative flex-1">
                <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input type="text" value={productSearch} onChange={(e) => setProductSearch(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") searchProducts(); }}
                  placeholder="Search product code or product name..."
                  className="w-full rounded-lg border bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" />
              </div>
              <button type="button" onClick={searchProducts} disabled={loadingProducts}
                className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50">
                {loadingProducts ? <Loader2 size={17} className="animate-spin" /> : <Search size={17} />} Search Products
              </button>
              <button type="button" onClick={clearSearch}
                className="inline-flex items-center justify-center gap-2 rounded-lg border bg-white px-5 py-2.5 text-sm font-semibold text-gray-700 hover:bg-gray-50">
                <X size={17} /> Clear
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-4 py-3 text-left"><input type="checkbox" checked={allProductsSelected} onChange={toggleSelectAll} disabled={products.length === 0} className="h-4 w-4" /></th>
                    <th className="px-4 py-3 text-left font-semibold text-gray-600">Product Code</th>
                    <th className="px-4 py-3 text-left font-semibold text-gray-600">Product Name</th>
                    <th className="px-4 py-3 text-left font-semibold text-gray-600">Department</th>
                    <th className="px-4 py-3 text-left font-semibold text-gray-600">Category</th>
                    <th className="px-4 py-3 text-left font-semibold text-gray-600">Supplier</th>
                    <th className="px-4 py-3 text-right font-semibold text-gray-600">Stock</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {products.length === 0 ? (
                    <tr><td colSpan="7" className="px-4 py-12 text-center">
                      <Package size={40} className="mx-auto mb-3 text-gray-300" />
                      <div className="font-medium text-gray-600">No products found</div>
                      <div className="mt-1 text-sm text-gray-400">Select filters and click Search Products.</div>
                    </td></tr>
                  ) : products.map((product, index) => (
                    <tr key={getProductID(product) || index} className="hover:bg-gray-50">
                      <td className="px-4 py-3"><input type="checkbox" checked={isSelected(product)} onChange={() => toggleProduct(product)} className="h-4 w-4" /></td>
                      <td className="px-4 py-3 font-medium text-gray-800">{product.ProductCode || "-"}</td>
                      <td className="px-4 py-3 text-gray-700">{product.ProductName || "-"}</td>
                      <td className="px-4 py-3 text-gray-600">{product.Department || "-"}</td>
                      <td className="px-4 py-3 text-gray-600">{product.Category || "-"}</td>
                      <td className="px-4 py-3 text-gray-600">{product.Supplier || "-"}</td>
                      <td className="px-4 py-3 text-right font-semibold text-gray-700">{Number(product.SystemStock || 0).toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="flex flex-col gap-4 border-t bg-gray-50 p-5 md:flex-row md:items-center md:justify-between">
              <div>
                <div className="text-sm font-medium text-gray-700">Selected Products: <span className="ml-2 rounded-full bg-blue-100 px-3 py-1 text-blue-700">{selectedProducts.length}</span></div>
                <div className="mt-1 text-xs text-gray-500">Location: {locationID || "Not available"}</div>
              </div>
              <button type="button" onClick={startSession} disabled={startingSession || selectedProducts.length === 0 || !locationID}
                className="inline-flex items-center justify-center gap-2 rounded-lg bg-green-600 px-6 py-3 text-sm font-bold text-white hover:bg-green-700 disabled:opacity-50">
                {startingSession ? <Loader2 size={18} className="animate-spin" /> : <Plus size={18} />} Start Stock Count
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default StockCount;