// src/hooks/usePermissions.jsx
// ============================================================
// Read-side hook for permissions. Delegates entirely to
// PermissionsContext.
//
// The hook no longer performs its own Firestore queries EXCEPT in
// one specific case: when PermissionsContext could not resolve a
// CashierID at all (ctx.cashierID == null). In that case it makes
// one direct attempt using the slower email/uid-based resolution —
// this covers the narrow window before AuthContext has populated
// localStorage.user.
//
// FIXES vs previous version
// ------------------------------------------------------------
//  • No more duplicate Firestore reads. The old code re-ran the
//    full network→cache→localStorage chain whenever ctx had 0
//    rows, producing 4× the Firestore calls per permission read.
//  • `isOffline` / `isStale` come straight from context.
//  • Slow-path CashierID resolution (email/uid queries) skipped
//    entirely when offline.
//  • Effect deps use primitives, so AuthContext's background
//    profile refresh doesn't trigger an infinite re-fetch loop.
// ============================================================
import {
  useContext,
  useEffect,
  useState,
  useMemo,
  useCallback,
} from "react";
import { PermissionsContext } from "../context/PermissionsContext";
import { AuthContext } from "../pos/SERVER/AuthContext";
import {
  collection,
  query,
  where,
  getDocs,
} from "firebase/firestore";
import { db } from "../firebase";

// ----------------------------------------------------------------
// Column mappings (unchanged)
// ----------------------------------------------------------------
const ACTION_TO_COLUMN = {
  View:   "CanView",
  Add:    "CanAdd",
  Edit:   "CanEdit",
  Delete: "CanDelete",
  Print:  "CanPrint",
};

const FIELD_TO_COLUMN = {
  CostPrice:       "CanViewCostPrice",
  SellingPrice:    "CanViewSellingPrice",
  Profit:          "CanViewProfit",
  CreditLimit:     "CanViewCreditLimit",
  MinimumDiscount: "CanViewMinimumDiscount",
  MaximumDiscount: "CanViewMaximumDiscount",
  PurchaseLimit:   "CanViewPurchaseLimit",
};

const COL_CASHIER = "cashier";

// ----------------------------------------------------------------
// Coercion / matching (unchanged)
// ----------------------------------------------------------------
const toBool = (v) => {
  if (v === true) return true;
  if (v === false) return false;
  if (v == null) return false;
  if (v === 1 || v === "1") return true;
  if (v === 0 || v === "0") return false;
  const s = String(v).trim().toLowerCase();
  if (s === "true" || s === "yes" || s === "y" || s === "on") return true;
  if (s === "false" || s === "no" || s === "n" || s === "off") return false;
  return Boolean(v);
};

const rowMatchesModule = (row, moduleName) => {
  if (!row || !moduleName) return false;
  const target = String(moduleName).trim().toLowerCase();
  const m = String(row.ModuleName || "").trim().toLowerCase();
  const p = String(row.PermissionName || "").trim().toLowerCase();
  return m === target || p === target;
};

const rowIsActive = (row) => {
  if (!row) return false;
  if (row.IsDelete === 1 || row.IsDelete === "1" || row.IsDelete === true) return false;
  if (row.IsActive === false || row.IsActive === 0 || row.IsActive === "0") return false;
  return true;
};

const isOfflineError = (err) => {
  if (!err) return false;
  const msg = String(err.message || err).toLowerCase();
  return (
    msg.includes("offline") ||
    msg.includes("unavailable") ||
    msg.includes("network") ||
    msg.includes("failed to get document") ||
    err.code === "unavailable"
  );
};

// ----------------------------------------------------------------
// Slow-path CashierID resolution (only used when ctx has none)
// ----------------------------------------------------------------
const readLegacyUser = () => {
  try {
    const raw = localStorage.getItem("user");
    if (!raw) return null;
    return JSON.parse(raw) || null;
  } catch {
    return null;
  }
};

const resolveCashierIdSlow = async (user) => {
  // If the browser is offline, don't even try Firestore — these
  // queries will hang and the caller only needs a "best effort".
  if (typeof navigator !== "undefined" && navigator.onLine === false) {
    console.warn("[usePermissions] offline — skipping slow CashierID resolution");
    return null;
  }

  if (!user) return null;

  const email = (user.email || user.Email || "").trim();
  const uid = user.uid || user.UID || "";

  const tryQuery = async (field, value) => {
    if (!value) return null;
    try {
      const snap = await getDocs(
        query(collection(db, COL_CASHIER), where(field, "==", value))
      );
      if (!snap.empty) {
        const d = snap.docs[0];
        const data = d.data();
        const cid = data.CashierID ?? data.CashierId ?? data.UserID ?? d.id;
        const n = Number(cid);
        if (Number.isFinite(n) && n > 0) return n;
      }
    } catch (err) {
      if (!isOfflineError(err)) {
        console.warn(
          `[usePermissions] cashier.${field} lookup failed:`,
          err?.message || err
        );
      }
    }
    return null;
  };

  if (email) {
    let r = await tryQuery("Email", email);    if (r) return r;
    r = await tryQuery("LogName", email);      if (r) return r;
    r = await tryQuery("UserName", email);     if (r) return r;
  }
  if (uid) {
    let r = await tryQuery("AuthUID", uid);    if (r) return r;
    r = await tryQuery("UID", uid);            if (r) return r;
  }

  return null;
};

// ----------------------------------------------------------------
// Hook
// ----------------------------------------------------------------
export function usePermissions() {
  const ctx = useContext(PermissionsContext);
  if (!ctx) throw new Error("usePermissions must be inside <PermissionsProvider>");

  const authCtx = useContext(AuthContext);
  const user = authCtx?.user || null;

  const [fallbackPerms, setFallbackPerms] = useState(null);
  const [fallbackLoading, setFallbackLoading] = useState(false);
  const [fallbackError, setFallbackError] = useState("");

  const ctxPermissions = Array.isArray(ctx.permissions) ? ctx.permissions : [];
  const ctxHasData = ctxPermissions.length > 0;
  const ctxLoading = Boolean(ctx.loading);
  const ctxCashierId = ctx.cashierID;

  // FIX: only run the fallback when the context genuinely could
  // NOT resolve a CashierID. If the context resolved one but
  // returned 0 rows, that's the *final* answer — no point retrying.
  useEffect(() => {
    if (ctxHasData) {
      setFallbackPerms(null);
      setFallbackError("");
      return;
    }

    // KEY CHANGE: if context has a cashierID, trust it. The empty
    // permissions list is intentional (either data doesn't exist,
    // or we're offline with no cache). Don't duplicate the work.
    if (ctxCashierId != null) {
      setFallbackPerms(null);
      setFallbackError("");
      return;
    }

    // No cashierID, no cache → try one direct attempt.
    if (ctxLoading) return;

    const legacy = readLegacyUser();
    if (!user && !legacy) return;

    let cancelled = false;

    (async () => {
      setFallbackLoading(true);
      setFallbackError("");
      try {
        console.info(
          "[usePermissions] ctx has no CashierID — attempting slow-path resolution…"
        );

        // Fast path first — legacy user may have been written
        // since the context mounted.
        const legacyId = legacy
          ? Number(
              legacy.CashierID ??
                legacy.CashierId ??
                legacy.cashierID ??
                legacy.cashierId
            )
          : NaN;

        let cashierId =
          Number.isFinite(legacyId) && legacyId > 0 ? legacyId : null;

        if (cashierId == null) {
          cashierId = await resolveCashierIdSlow(user);
        }

        if (cancelled) return;

        if (cashierId == null) {
          setFallbackPerms([]);
          return;
        }

        // The context should pick up this cashierId on the next
        // render (via its memoised `resolvedCashierId`). Until then,
        // the hook returns [] — the real load will come from the
        // context, not from us.
        console.info(
          `[usePermissions] slow-path resolved CashierID=${cashierId} — ` +
          `context will hydrate on next render`
        );
        setFallbackPerms([]);
      } catch (err) {
        if (!cancelled) {
          setFallbackError(err?.message || String(err));
          setFallbackPerms([]);
        }
      } finally {
        if (!cancelled) setFallbackLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [
    ctxHasData,
    ctxLoading,
    ctxCashierId,
    user?.CashierID,
    user?.uid,
    user?.email,
  ]);

  // Effective permissions — context wins, hook fallback second.
  const permissions = useMemo(() => {
    if (ctxHasData) return ctxPermissions;
    if (Array.isArray(fallbackPerms)) return fallbackPerms;
    return [];
  }, [ctxHasData, ctxPermissions, fallbackPerms]);

  const loading = ctxLoading || fallbackLoading;
  const error = ctx.error || fallbackError || "";

  // `can(moduleName, action)`
  const can = useCallback(
    (moduleName, action = "View") => {
      const column = ACTION_TO_COLUMN[action] || action;
      if (!moduleName || permissions.length === 0) return false;
      const match = permissions.find(
        (row) => rowMatchesModule(row, moduleName) && rowIsActive(row)
      );
      return match ? toBool(match[column]) : false;
    },
    [permissions]
  );

  // `canField(moduleName, field)`
  const canField = useCallback(
    (moduleName, field) => {
      const column = FIELD_TO_COLUMN[field];
      if (!column) return true;
      if (!moduleName || permissions.length === 0) return false;
      const match = permissions.find(
        (row) => rowMatchesModule(row, moduleName) && rowIsActive(row)
      );
      if (!match) return false;
      if (column in match && match[column] != null) return toBool(match[column]);
      return toBool(match.CanView);
    },
    [permissions]
  );

  // Pass-through reload — hits the context, which triggers a
  // network refresh attempt.
  const reload = useCallback(() => {
    setFallbackPerms(null);
    setFallbackError("");
    try {
      if (typeof ctx.reload === "function") ctx.reload();
    } catch (err) {
      console.warn("[usePermissions] ctx.reload threw:", err);
    }
  }, [ctx]);

  return {
    permissions,
    loading,
    error,
    isOffline: Boolean(ctx.isOffline),
    isStale: Boolean(ctx.isStale),
    cachedAt: ctx.cachedAt || null,
    cashierID: ctxCashierId,
    reload,
    can,
    canField,
  };
}