// src/pos/subcatagory.js
// ============================================================
// SubCategory Master — React + Firestore
// ------------------------------------------------------------
// Preserves:
//   • Dependent department → category dropdown
//   • Auto-generated subcategory code (001, 002, ...)
//   • Edit / soft-delete / search
//   • Full permission gating (View / Add / Edit / Delete)
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import {
  listCollection,
  createDoc,
  updateDocById,
  softDeleteDoc,
  nextSubCategoryCode,
} from "../lib/firestore";

const emptyForm = {
  DepartmentCode: "",
  Department: "",
  Category: "",
  SubCategoryCode: "",
  SubCategoryName: "",
  Remark: "",
};

export default function Subcatagory() {
  const { user } = useContext(AuthContext);
  const { can, loading: permissionsLoading } = usePermissions();

  // ---- PERMISSIONS ----
  const canViewSubCategory   = can("SubCategory", "View");
  const canAddSubCategory    = can("SubCategory", "Add");
  const canEditSubCategory   = can("SubCategory", "Edit");
  const canDeleteSubCategory = can("SubCategory", "Delete");

  // ---- STATE ----
  const [form, setForm]                 = useState(emptyForm);
  const [departments, setDepartments]   = useState([]);
  const [categories, setCategories]     = useState([]);
  const [subcategories, setSubcategories] = useState([]);
  const [search, setSearch]             = useState("");
  const [editingId, setEditingId]       = useState(null); // Firestore doc id

  const [loading,     setLoading]     = useState(false);
  const [loadingCode, setLoadingCode] = useState(false);
  const [saving,      setSaving]      = useState(false);
  const [deleting,    setDeleting]    = useState(false);

  const [message, setMessage] = useState("");
  const [error,   setError]   = useState("");

  // ============================================================
  // LOAD DEPARTMENTS + CATEGORIES + SUBCATEGORIES
  // ============================================================
  const loadDepartments = async () => {
    const rows = await listCollection("Department", {
      where: [["IsDelete", "==", 0]],
    });
    rows.sort((a, b) =>
      String(a.DepartmentName || "").localeCompare(String(b.DepartmentName || ""))
    );
    setDepartments(rows);
  };

  const loadCategories = async () => {
    const rows = await listCollection("Category", {
      where: [["IsDelete", "==", 0]],
    });
    rows.sort((a, b) =>
      String(a.CategoryName || "").localeCompare(String(b.CategoryName || ""))
    );
    setCategories(rows);
  };

  const loadSubCategories = async () => {
    try {
      setLoading(true);
      const rows = await listCollection("SubCategory", {
        where: [["IsDelete", "==", 0]],
      });
      rows.sort((a, b) =>
        String(a.SubCategoryName || "").localeCompare(String(b.SubCategoryName || ""))
      );
      setSubcategories(rows);
    } catch (err) {
      console.error("LOAD SUBCATEGORIES ERROR:", err);
      setError(err?.message || "Unable to load subcategories.");
      setSubcategories([]);
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // INITIAL LOAD
  // ============================================================
  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewSubCategory) return;

    (async () => {
      try {
        setError("");
        await Promise.all([loadDepartments(), loadCategories()]);
        await loadSubCategories();
      } catch (err) {
        console.error("INITIAL LOAD ERROR:", err);
        setError(err?.message || "Unable to load master data.");
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewSubCategory]);

  // ============================================================
  // INPUT
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((p) => ({ ...p, [name]: value }));
    setMessage("");
    setError("");
  };

  // ============================================================
  // DEPARTMENT CHANGE
  // ============================================================
  const handleDepartmentChange = (e) => {
    const departmentCode = e.target.value;
    const selected = departments.find(
      (d) => String(d.DepartmentCode) === String(departmentCode)
    );
    const departmentText = selected
      ? `${selected.DepartmentCode} - ${selected.DepartmentName}`
      : "";

    setForm((p) => ({
      ...p,
      DepartmentCode: departmentCode,
      Department:     departmentText,
      Category:       "",
    }));
    setMessage("");
    setError("");
  };

  // ============================================================
  // CATEGORY LIST FILTERED BY SELECTED DEPARTMENT
  // ------------------------------------------------------------
  // Category.Department is stored as "<Code> - <Name>" text.
  // Match against either the code, the full text, or prefix.
  // ============================================================
  const filteredCategories = useMemo(() => {
    if (!form.DepartmentCode) return [];
    const selectedCode = String(form.DepartmentCode).trim();
    const selectedDept = String(form.Department).trim();

    return categories.filter((c) => {
      const d = String(c.Department || "").trim();
      return (
        d === selectedCode ||
        d === selectedDept ||
        d.startsWith(`${selectedCode} -`)
      );
    });
  }, [categories, form.DepartmentCode, form.Department]);

  const handleCategoryChange = (e) => {
    const value = e.target.value;
    setForm((p) => ({ ...p, Category: value }));
    setMessage("");
    setError("");
  };

  // ============================================================
  // NEW — generate next code, keep current dept/category selection
  // ============================================================
  const handleNew = async () => {
    if (!canAddSubCategory) {
      setError("You do not have permission to create subcategories.");
      return;
    }
    try {
      setLoadingCode(true);
      setMessage("");
      setError("");

      const nextCode = await nextSubCategoryCode();

      setForm((p) => ({
        ...p,
        SubCategoryCode: nextCode,
        SubCategoryName: "",
        Remark:          "",
      }));
      setEditingId(null);
      setMessage(`New subcategory code generated: ${nextCode}`);
    } catch (err) {
      console.error("GENERATE SUBCATEGORY CODE ERROR:", err);
      setError(err?.message || "Unable to generate subcategory code.");
    } finally {
      setLoadingCode(false);
    }
  };

  // ============================================================
  // SAVE / UPDATE
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    // Permission gates
    if (editingId && !canEditSubCategory) {
      setError("You do not have permission to edit subcategories.");
      return;
    }
    if (!editingId && !canAddSubCategory) {
      setError("You do not have permission to create subcategories.");
      return;
    }

    // Validation
    const departmentCode  = String(form.DepartmentCode  ?? "").trim();
    const category        = String(form.Category        ?? "").trim();
    const subCategoryCode = String(form.SubCategoryCode ?? "").trim();
    const subCategoryName = String(form.SubCategoryName ?? "").trim();
    const remark          = String(form.Remark          ?? "").trim();

    if (!departmentCode)  { setError("Please select Department.");       return; }
    if (!category)        { setError("Please select Category.");         return; }
    if (!subCategoryCode) { setError("Please enter SubCategory Code.");  return; }
    if (!subCategoryName) { setError("Please enter SubCategory Name.");  return; }
    if (subCategoryCode.length > 15) { setError("Code cannot exceed 15 characters."); return; }
    if (subCategoryName.length > 50) { setError("Name cannot exceed 50 characters."); return; }
    if (remark.length > 150)         { setError("Remark cannot exceed 150 characters."); return; }

    try {
      setSaving(true);

      // Duplicate code check on create
      if (!editingId) {
        const existing = await listCollection("SubCategory", {
          where: [
            ["IsDelete", "==", 0],
            ["SubCategoryCode", "==", subCategoryCode],
          ],
          limit: 1,
        });
        if (existing.length > 0) {
          setError(`SubCategory code "${subCategoryCode}" already exists.`);
          return;
        }
      }

      const payload = {
        DepartmentCode:  departmentCode,
        Department:      form.Department.trim(),
        Category:        category,
        SubCategoryCode: subCategoryCode,
        SubCategoryName: subCategoryName,
        Remark:          remark || null,
        IsDelete: 0,
        IsActive: 1,
      };

      if (editingId) {
        await updateDocById("SubCategory", editingId, payload, {
          username: user?.username,
        });
        setMessage("SubCategory updated successfully.");
      } else {
        await createDoc("SubCategory", payload, {
          username: user?.username,
        });
        setMessage("SubCategory saved successfully.");
      }

      // Preserve current department + category selection and pre-generate next code
      const currentDepartmentCode = form.DepartmentCode;
      const currentDepartment     = form.Department;
      const currentCategory       = form.Category;
      const nextCode              = await nextSubCategoryCode();

      setForm({
        DepartmentCode:  currentDepartmentCode,
        Department:      currentDepartment,
        Category:        currentCategory,
        SubCategoryCode: nextCode,
        SubCategoryName: "",
        Remark:          "",
      });
      setEditingId(null);

      await loadSubCategories();
    } catch (err) {
      console.error("SAVE SUBCATEGORY ERROR:", err);
      setError(err?.message || "Error saving SubCategory.");
    } finally {
      setSaving(false);
    }
  };

  // ============================================================
  // EDIT
  // ============================================================
  const handleEdit = (item) => {
    if (!canEditSubCategory) {
      setError("You do not have permission to edit subcategories.");
      return;
    }

    // Resolve department code from stored Department text
    let departmentCode = item.DepartmentCode || "";
    let departmentText = item.Department || "";

    if (!departmentCode && departmentText) {
      const trimmed = String(departmentText).trim();
      const found = departments.find((d) => {
        const full = `${d.DepartmentCode} - ${d.DepartmentName}`;
        return (
          String(d.DepartmentCode).trim() === trimmed ||
          String(d.DepartmentName).trim() === trimmed ||
          full.trim() === trimmed
        );
      });
      if (found) {
        departmentCode = found.DepartmentCode;
        departmentText = `${found.DepartmentCode} - ${found.DepartmentName}`;
      }
    }

    // Resolve category value from stored Category text
    const categoryValue =
      item.Category ||
      (item.CategoryCode && item.CategoryName
        ? `${item.CategoryCode} - ${item.CategoryName}`
        : "");

    setForm({
      DepartmentCode:  departmentCode,
      Department:      departmentText,
      Category:        categoryValue,
      SubCategoryCode: item.SubCategoryCode || "",
      SubCategoryName: item.SubCategoryName || "",
      Remark:          item.Remark || "",
    });

    setEditingId(item.id);
    setMessage(`Editing ${item.SubCategoryCode}`);
    setError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE
  // ============================================================
  const handleDelete = async (item) => {
    if (!canDeleteSubCategory) {
      setError("You do not have permission to delete subcategories.");
      return;
    }
    if (!item?.id) {
      setError("Invalid SubCategory ID.");
      return;
    }
    const confirmed = window.confirm(
      `Are you sure you want to delete this SubCategory?\n\n${item.SubCategoryCode} - ${item.SubCategoryName}`
    );
    if (!confirmed) return;

    try {
      setDeleting(true);
      setMessage("");
      setError("");

      await softDeleteDoc("SubCategory", item.id, {
        username: user?.username,
      });
      setMessage("SubCategory deleted successfully.");

      if (editingId === item.id) {
        setEditingId(null);
        setForm((p) => ({
          ...p,
          SubCategoryCode: "",
          SubCategoryName: "",
          Remark:          "",
        }));
      }
      await loadSubCategories();
    } catch (err) {
      console.error("DELETE SUBCATEGORY ERROR:", err);
      setError(err?.message || "Error deleting SubCategory.");
    } finally {
      setDeleting(false);
    }
  };

  // ============================================================
  // CANCEL EDIT
  // ============================================================
  const handleCancel = () => {
    setEditingId(null);
    setForm((p) => ({
      ...p,
      SubCategoryCode: "",
      SubCategoryName: "",
      Remark:          "",
    }));
    setMessage("");
    setError("");
  };

  // ============================================================
  // SEARCH
  // ============================================================
  const searchText = search.trim().toLowerCase();
  const filteredSubCategories = useMemo(() => {
    if (!searchText) return subcategories;
    return subcategories.filter((item) => {
      const code   = String(item.SubCategoryCode ?? "").toLowerCase();
      const name   = String(item.SubCategoryName ?? "").toLowerCase();
      const cat    = String(item.Category        ?? "").toLowerCase();
      const dept   = String(item.Department      ?? "").toLowerCase();
      return (
        code.includes(searchText) ||
        name.includes(searchText) ||
        cat.includes(searchText)  ||
        dept.includes(searchText)
      );
    });
  }, [subcategories, searchText]);

  // ============================================================
  // COMPUTED
  // ============================================================
  const isEditing    = Boolean(editingId);
  const saveAllowed  = (isEditing && canEditSubCategory) || (!isEditing && canAddSubCategory);
  const readOnlyEdit = isEditing && !canEditSubCategory;

  // ============================================================
  // ACCESS GATE
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewSubCategory) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view SubCategory Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>SubCategory</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">

        {/* HEADER */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-sm">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-800">SubCategory Master</h1>
              <p className="mt-1 text-sm text-gray-500">
                Create and manage product subcategories
              </p>
            </div>

            <div className="flex items-center gap-2">
              {readOnlyEdit && (
                <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
                  READ ONLY
                </span>
              )}
              <div className="rounded-lg border border-gray-200 bg-gray-50 px-4 py-2 text-sm text-gray-700">
                <span className="text-xs text-gray-500">User: </span>
                <span className="font-semibold">{user?.username || "—"}</span>
              </div>
              {canAddSubCategory && (
                <button
                  type="button"
                  onClick={handleNew}
                  className="rounded-lg bg-blue-600 px-5 py-2.5 font-semibold text-white shadow-sm transition hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-300"
                >
                  + New
                </button>
              )}
              {isEditing && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-lg bg-gray-500 px-5 py-2.5 font-semibold text-white transition hover:bg-gray-600"
                >
                  Cancel
                </button>
              )}
            </div>
          </div>
        </div>

        {/* MESSAGES */}
        {message && (
          <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
            ✓ {message}
          </div>
        )}
        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
            ⚠ {error}
          </div>
        )}

        {/* FORM */}
        <div className="mb-6 rounded-xl bg-white p-5 shadow-sm">
          <div className="mb-4 flex items-center justify-between border-b pb-3">
            <h2 className="text-lg font-semibold text-gray-800">
              {isEditing ? "Edit SubCategory" : "SubCategory Information"}
            </h2>
            {isEditing && (
              <span className="rounded-full bg-orange-100 px-3 py-1 text-xs font-bold text-orange-700">
                EDIT MODE
              </span>
            )}
          </div>

          <form onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">

              {/* DEPARTMENT */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Department <span className="ml-1 text-red-500">*</span>
                </label>
                <select
                  value={form.DepartmentCode}
                  onChange={handleDepartmentChange}
                  disabled={isEditing}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200 disabled:bg-gray-100"
                >
                  <option value="">-- Select Department --</option>
                  {departments.map((department) => (
                    <option key={department.id} value={department.DepartmentCode}>
                      {department.DepartmentCode} - {department.DepartmentName}
                    </option>
                  ))}
                </select>
                {departments.length === 0 && (
                  <p className="mt-1 text-xs text-red-500">No departments found.</p>
                )}
              </div>

              {/* CATEGORY */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Category <span className="ml-1 text-red-500">*</span>
                </label>
                <select
                  value={form.Category}
                  onChange={handleCategoryChange}
                  disabled={!form.DepartmentCode}
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-sm text-gray-800 disabled:cursor-not-allowed disabled:bg-gray-100 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                >
                  <option value="">
                    {!form.DepartmentCode
                      ? "-- Select Department First --"
                      : "-- Select Category --"}
                  </option>
                  {filteredCategories.map((category) => {
                    const value = `${category.CategoryCode} - ${category.CategoryName}`;
                    return (
                      <option key={category.id} value={value}>
                        {value}
                      </option>
                    );
                  })}
                </select>
                {form.DepartmentCode && filteredCategories.length === 0 && (
                  <p className="mt-1 text-xs text-orange-500">
                    No categories found for this department.
                  </p>
                )}
              </div>

              {/* SUBCATEGORY CODE */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  SubCategory Code <span className="ml-1 text-red-500">*</span>
                </label>
                <div className="flex gap-2">
                  <input
                    type="text"
                    name="SubCategoryCode"
                    value={form.SubCategoryCode}
                    onChange={handleChange}
                    disabled={isEditing}
                    placeholder="001"
                    className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm disabled:cursor-not-allowed disabled:bg-gray-100 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                  />
                  {!isEditing && canAddSubCategory && (
                    <button
                      type="button"
                      onClick={handleNew}
                      disabled={loadingCode}
                      className="min-w-[90px] rounded-lg bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 disabled:bg-gray-400"
                    >
                      {loadingCode ? "…" : "New"}
                    </button>
                  )}
                </div>
              </div>

              {/* SUBCATEGORY NAME */}
              <div>
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  SubCategory Name <span className="ml-1 text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="SubCategoryName"
                  value={form.SubCategoryName}
                  onChange={handleChange}
                  placeholder="Enter SubCategory Name"
                  maxLength={50}
                  className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                />
              </div>

              {/* REMARK */}
              <div className="md:col-span-2">
                <label className="mb-1 block text-sm font-semibold text-gray-700">
                  Remark
                </label>
                <textarea
                  name="Remark"
                  value={form.Remark}
                  onChange={handleChange}
                  placeholder="Enter remark"
                  maxLength={150}
                  rows={3}
                  className="w-full resize-none rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                />
              </div>
            </div>

            {/* BUTTONS */}
            <div className="mt-6 flex flex-wrap gap-3">
              {saveAllowed && (
                <button
                  type="submit"
                  disabled={saving || deleting}
                  className="rounded-lg bg-green-600 px-6 py-2.5 font-semibold text-white shadow-sm transition hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {saving ? "Saving…" : isEditing ? "Update SubCategory" : "Save SubCategory"}
                </button>
              )}

              {isEditing && (
                <button
                  type="button"
                  onClick={handleCancel}
                  className="rounded-lg bg-gray-500 px-6 py-2.5 font-semibold text-white transition hover:bg-gray-600"
                >
                  Cancel
                </button>
              )}

              {readOnlyEdit && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You have read-only access — editing is disabled.
                </div>
              )}

              {!isEditing && !canAddSubCategory && (
                <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
                  You do not have permission to create new subcategories.
                </div>
              )}
            </div>
          </form>
        </div>

        {/* SEARCH */}
        <div className="mb-4 rounded-xl bg-white p-4 shadow-sm">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="w-full md:max-w-md">
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Search SubCategories
              </label>
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search code, name, category..."
                className="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
              />
            </div>
            <div className="text-sm text-gray-500">
              Total:{" "}
              <span className="font-semibold text-gray-800">
                {filteredSubCategories.length}
              </span>
            </div>
          </div>
        </div>

        {/* TABLE */}
        <div className="overflow-hidden rounded-xl bg-white shadow-sm">
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-gray-800 text-white">
                <tr>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">#</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Department</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Category</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Code</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">SubCategory Name</th>
                  <th className="whitespace-nowrap px-4 py-3 text-left font-semibold">Remark</th>
                  <th className="whitespace-nowrap px-4 py-3 text-center font-semibold">Actions</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-200">
                {loading && subcategories.length === 0 ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-500">
                      Loading SubCategories…
                    </td>
                  </tr>
                ) : filteredSubCategories.length === 0 ? (
                  <tr>
                    <td colSpan="7" className="px-4 py-8 text-center text-gray-500">
                      No SubCategories found.
                    </td>
                  </tr>
                ) : (
                  filteredSubCategories.map((item, index) => (
                    <tr
                      key={item.id || index}
                      className="transition hover:bg-gray-50"
                    >
                      <td className="px-4 py-3 text-gray-600">{index + 1}</td>
                      <td className="px-4 py-3 font-medium text-gray-700">
                        {item.Department || "-"}
                      </td>
                      <td className="px-4 py-3 text-gray-700">
                        {item.Category || "-"}
                      </td>
                      <td className="px-4 py-3 font-semibold text-blue-600">
                        {item.SubCategoryCode || "-"}
                      </td>
                      <td className="px-4 py-3 font-medium text-gray-800">
                        {item.SubCategoryName || "-"}
                      </td>
                      <td className="max-w-xs px-4 py-3 text-gray-600">
                        {item.Remark || "-"}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex justify-center gap-2">
                          {canEditSubCategory && (
                            <button
                              type="button"
                              onClick={() => handleEdit(item)}
                              disabled={deleting}
                              className="rounded-md bg-blue-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-blue-600 disabled:opacity-50"
                            >
                              Edit
                            </button>
                          )}
                          {canDeleteSubCategory && (
                            <button
                              type="button"
                              onClick={() => handleDelete(item)}
                              disabled={deleting}
                              className="rounded-md bg-red-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-red-600 disabled:opacity-50"
                            >
                              Delete
                            </button>
                          )}
                          {!canEditSubCategory && !canDeleteSubCategory && (
                            <span className="text-xs text-slate-400">No actions</span>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}