import React, { useContext, useEffect } from "react";
import './index.css';
import { AuthContext } from "./pos/SERVER/AuthContext.js";
import { useNavigate } from "react-router-dom";

function Homes() {
  const navigate = useNavigate();
  const auth = useContext(AuthContext);

  // Accept multiple shapes — the provider might expose `user`, `currentUser`,
  // `auth.user`, or the raw user object.
  const user =
    auth?.user ??
    auth?.currentUser ??
    auth?.loggedInUser ??
    (auth && typeof auth === "object" && !Array.isArray(auth) && auth.username
      ? auth
      : null);

  // Accept multiple loading flags — some providers call it `loading`,
  // some `authLoading` or `initializing`, some don't expose it at all.
  const loading =
    auth?.loading === true ||
    auth?.authLoading === true ||
    auth?.initializing === true;

  // Try every common field name for the display text
  const displayName =
    user?.username ||
    user?.UserName ||
    user?.name ||
    user?.Name ||
    user?.email ||
    user?.Email ||
    "";

  // Print the diagnostic once so you can see what's actually there
  useEffect(() => {
    console.log("Homes — AuthContext value:", auth);
    console.log("Homes — resolved user:", user);
    console.log("Homes — displayName:", displayName);
    console.log("Homes — loading:", loading);
    console.log(
      "Homes — localStorage.user:",
      (() => { try { return localStorage.getItem("user"); } catch { return "n/a"; } })()
    );
  }, [auth, user, displayName, loading]);

  // If genuinely not logged in after loading finishes → redirect to login.
  // Delete this effect if your app handles the redirect in a ProtectedRoute.
  useEffect(() => {
    if (!loading && auth && !user && !displayName) {
      // Avoid redirect loop if /login is this same route
      if (window.location.pathname !== "/login") {
        navigate("/login", { replace: true });
      }
    }
  }, [loading, auth, user, displayName, navigate]);

  // Don't flash "No user logged in" while the provider is hydrating
  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-[#e0e5ec]">
        <div className="text-slate-500 text-lg">Loading…</div>
      </div>
    );
  }

  return (
    <div className="h-screen flex items-center justify-center bg-[#e0e5ec]">
      <div className="flex flex-col items-center gap-6">
        <div className="text-lg font-semibold text-slate-700">
          {displayName ? `Welcome, ${displayName}` : "No user logged in"}
        </div>

        <div className="flex gap-6">
          <button
            className="px-10 py-5 text-xl font-semibold rounded-2xl bg-blue-500 text-white shadow-xl shadow-blue-300/50 hover:scale-110 hover:shadow-blue-400/70 active:scale-95 active:shadow-inner transition-all duration-200"
            onClick={() => navigate("/sidebar")}
          >
            POS
          </button>

          <button
            className="px-10 py-5 text-xl font-semibold rounded-2xl bg-green-500 text-white shadow-xl shadow-green-300/50 hover:scale-110 hover:shadow-green-400/70 active:scale-95 active:shadow-inner transition-all duration-200"
            onClick={() => navigate("/ERP")}
          >
            ERP
          </button>

          <button
            className="px-10 py-5 text-xl font-semibold rounded-2xl bg-purple-500 text-white shadow-xl shadow-purple-300/50 hover:scale-110 hover:shadow-purple-400/70 active:scale-95 active:shadow-inner transition-all duration-200"
            onClick={() => navigate("/PosSetting")}
          >
            ADMIN
          </button>
        </div>
      </div>
    </div>
  );
}

export default Homes;