// src/pos/SERVER/AuthContext.jsx
// Authentication context with safe cashier identity hydration.
//
// CashierID priority:
//   1. localStorage.user           (fast, offline, mirrored by persistUser)
//   2. auth.profile.<uid>          (fast, offline, cached profile)
//   3. Firestore profile document  (authoritative, network)
//
// FIXES IN THIS REVISION
// ------------------------------------------------------------
//  1. persistUser() now writes BOTH cacheKey(uid) AND the legacy
//     `user` key — previously nothing ever wrote localStorage.user,
//     so the documented #1 priority tier was always empty.
//  2. profileReady users are persisted immediately on login, so
//     subsequent OFFLINE sessions hydrate from cache without
//     touching Firestore at all.
//  3. readProfileByUid() short-circuits after the first network
//     failure (was 8s × 4 collections = 32s worst-case; now ~3s).
//  4. Skips network entirely when navigator.onLine === false.
//  5. withTimeout() clears its timer and swallows the losing
//     promise's rejection (no more unhandled-rejection warnings).
//  6. Online listener auto-refreshes the profile when the network
//     comes back, without requiring a page reload.
//  7. A `profileSyncedAt` timestamp is stored so the UI can show
//     "data from X minutes ago" when reading from cache.

import React, {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
} from "firebase/auth";
import { doc, getDoc, getDocFromCache } from "firebase/firestore";
import { auth, db } from "../../firebase.js";

export const AuthContext = createContext(null);

const PROFILE_COLLECTIONS = ["Cashier", "cashier", "Users", "users"];
const PROFILE_TIMEOUT_MS = 3000; // was 8000 — see fix #3
const LEGACY_USER_KEY = "user";

const cacheKey = (uid) => `auth.profile.${uid}`;

/* ---------- normalization / small helpers ---------- */

const normalizeCashierId = (value) => {
  if (value == null || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
};

const firstCashierId = (...sources) => {
  for (const source of sources) {
    if (!source || typeof source !== "object") continue;
    const value =
      source.CashierID ??
      source.CashierId ??
      source.cashierID ??
      source.cashierId;
    const id = normalizeCashierId(value);
    if (id != null) return id;
  }
  return null;
};

const parseObject = (raw) => {
  if (!raw) return null;
  try {
    const value = JSON.parse(raw);
    return value && typeof value === "object" && !Array.isArray(value)
      ? value
      : null;
  } catch {
    return null;
  }
};

const readLegacyUser = () => {
  try {
    return parseObject(localStorage.getItem(LEGACY_USER_KEY));
  } catch {
    return null;
  }
};

const readCache = (uid) => {
  try {
    return parseObject(localStorage.getItem(cacheKey(uid)));
  } catch {
    return null;
  }
};

/**
 * FIX #1: write both the new cache key AND the legacy `user` key so
 * that every consumer (Homes.jsx, PermissionsContext, any older
 * module still reading localStorage.user) sees the same state.
 */
const persistUser = (user) => {
  if (!user?.uid) return;
  try {
    const payload = {
      ...user,
      profileSyncedAt: new Date().toISOString(),
    };
    localStorage.setItem(cacheKey(user.uid), JSON.stringify(payload));

    // Only mirror to the legacy key when we actually have identity data —
    // never write a bare Firebase User to localStorage.user.
    if (user.CashierID != null || user.email) {
      localStorage.setItem(LEGACY_USER_KEY, JSON.stringify(payload));
    }
  } catch {
    // Storage may be disabled or full; auth should still work.
  }
};

const clearCache = (uid) => {
  try {
    localStorage.removeItem(cacheKey(uid));
  } catch {
    // Ignore storage errors during logout.
  }
};

const clearLegacyUser = () => {
  try {
    localStorage.removeItem(LEGACY_USER_KEY);
  } catch {
    // Ignore storage errors during logout.
  }
};

/**
 * FIX #5: clear the timer and swallow the losing promise's
 * rejection so we don't generate unhandled-rejection warnings.
 */
const withTimeout = (promise, ms, label) => {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(
      () => reject(new Error(`${label} timed out`)),
      ms
    );
  });

  // Prevent an unhandled rejection if the original promise rejects
  // *after* the timeout has already won the race.
  promise.catch(() => {});

  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
};

const legacyMatchesAuthUser = (legacy, fbUser) => {
  if (!legacy) return false;

  const legacyEmail = String(legacy.email ?? legacy.Email ?? "")
    .trim()
    .toLowerCase();
  const authEmail = String(fbUser?.email ?? "").trim().toLowerCase();

  if (legacyEmail && authEmail && legacyEmail !== authEmail) return false;
  return true;
};

const buildUser = (fbUser, { legacy, cache, profile } = {}) => {
  const safeLegacy = legacyMatchesAuthUser(legacy, fbUser) ? legacy : null;

  const merged = {
    ...(profile || {}),
    ...(cache || {}),
    ...(safeLegacy || {}),
  };

  const cashierId = firstCashierId(safeLegacy, cache, profile);

  return {
    ...merged,
    uid: fbUser.uid,
    email: fbUser.email || merged.email || merged.Email || "",
    CashierID: cashierId,
  };
};

/* ---------- profile read ---------- */

/**
 * FIX #3 + #4: read the profile from cache first, then from the
 * network — but ONLY if the browser reports being online. After the
 * first network failure, stop trying the remaining collection names
 * (they're all on the same Firestore instance, so if one is offline,
 * all four are).
 */
async function readProfileByUid(fbUser) {
  const browserOffline =
    typeof navigator !== "undefined" && navigator.onLine === false;
  let networkDead = browserOffline;

  for (const collectionName of PROFILE_COLLECTIONS) {
    const profileRef = doc(db, collectionName, fbUser.uid);

    // Cache hit — always try, always cheap.
    try {
      const cached = await getDocFromCache(profileRef);
      if (cached?.exists()) {
        console.info(
          `[Auth] Profile from cache: ${collectionName}/${fbUser.uid}`
        );
        return { id: cached.id, ...cached.data() };
      }
    } catch {
      // Not in Firestore's IndexedDB cache — normal on a fresh session.
    }

    if (networkDead) continue;

    const t0 = performance.now();
    try {
      const snapshot = await withTimeout(
        getDoc(profileRef),
        PROFILE_TIMEOUT_MS,
        `${collectionName}/${fbUser.uid}`
      );

      if (snapshot?.exists()) {
        console.info(
          `[Auth] Profile from server: ${collectionName}/${fbUser.uid} in ${(
            performance.now() - t0
          ).toFixed(0)}ms`
        );
        return { id: snapshot.id, ...snapshot.data() };
      }
      // Doc doesn't exist under this name — try the next collection.
    } catch (error) {
      console.warn(
        `[Auth] Could not read ${collectionName}/${fbUser.uid} (${(
          performance.now() - t0
        ).toFixed(0)}ms):`,
        error?.message || error
      );

      // FIX #3: short-circuit remaining network attempts once we know
      // Firestore itself is unreachable.
      if (
        error?.code === "unavailable" ||
        /offline|timed out|network/i.test(String(error?.message || ""))
      ) {
        networkDead = true;
      }
    }
  }

  console.warn(
    `[Auth] No profile document found for uid ${fbUser.uid} in any of:`,
    PROFILE_COLLECTIONS.join(", ")
  );
  return null;
}

/* ---------- provider ---------- */

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [profileLoading, setProfileLoading] = useState(false);
  const [error, setError] = useState("");

  const activeUidRef = useRef(null);
  const fbUserRef = useRef(null);   // for the online listener
  const userRef = useRef(null);     // mirrors `user` synchronously

  // Keep refs in sync so listeners see the latest values without
  // re-subscribing.
  useEffect(() => {
    userRef.current = user;
  }, [user]);

  /**
   * Extract the profile-refresh logic so it can be called both from
   * onAuthStateChanged AND from the online/offline listener.
   */
  const doRefreshProfile = useCallback(
    async (fbUser, { legacy, cached } = {}) => {
      if (!fbUser) return;

      setProfileLoading(true);
      try {
        const profile = await readProfileByUid(fbUser);

        if (activeUidRef.current !== fbUser.uid) return; // account changed

        if (!profile) {
          // No profile found. Leave whatever we already had (cache /
          // legacy) untouched — never downgrade a known CashierID.
          setUser((prev) =>
            prev?.uid === fbUser.uid
              ? { ...prev, profileReady: prev.CashierID != null }
              : prev
          );
          return;
        }

        // Merge with whatever the initial identity had, so a partial
        // profile document can't erase cached fields.
        const prev = userRef.current;
        if (!prev || prev.uid !== fbUser.uid) return;

        const refreshed = buildUser(fbUser, {
          legacy,
          cache: cached,
          profile,
        });
        const cashierId =
          refreshed.CashierID ?? normalizeCashierId(prev.CashierID);

        const finalUser = {
          ...prev,
          ...refreshed,
          CashierID: cashierId,
          profileReady: cashierId != null,
        };

        userRef.current = finalUser;   // keep ref in sync before setUser
        setUser(finalUser);

        // FIX #2: persist immediately so future offline sessions
        // hydrate from cache with zero Firestore calls.
        persistUser(finalUser);

        console.info("[Auth] Profile refresh complete:", {
          uid: fbUser.uid,
          profileDocumentId: profile.id,
          profileCashierID: firstCashierId(profile),
          resolvedCashierID: cashierId,
        });
      } catch (refreshError) {
        console.warn(
          "[Auth] Background profile refresh failed:",
          refreshError?.message || refreshError
        );
      } finally {
        if (activeUidRef.current === fbUser.uid) {
          setProfileLoading(false);
        }
      }
    },
    []
  );

  const refreshProfileRef = useRef(doRefreshProfile);
  refreshProfileRef.current = doRefreshProfile;

  /* ---------- primary auth listener ---------- */

  useEffect(() => {
    let disposed = false;

    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      if (!fbUser) {
        activeUidRef.current = null;
        fbUserRef.current = null;
        userRef.current = null;
        setUser(null);
        setProfileLoading(false);
        setLoading(false);
        return;
      }

      activeUidRef.current = fbUser.uid;
      fbUserRef.current = fbUser;

      const rawLegacy = readLegacyUser();
      const legacy = legacyMatchesAuthUser(rawLegacy, fbUser)
        ? rawLegacy
        : null;
      const cached = readCache(fbUser.uid);
      const initialUser = buildUser(fbUser, { legacy, cache: cached });

      if (disposed || activeUidRef.current !== fbUser.uid) return;

      const withReady = {
        ...initialUser,
        profileReady: initialUser.CashierID != null,
      };

      userRef.current = withReady;
      setUser(withReady);
      setLoading(false);

      // FIX #2: if we already have a CashierID from legacy/cache,
      // persist immediately so the next offline session is instant.
      if (withReady.CashierID != null) {
        persistUser(withReady);
      }

      console.info("[Auth] Initial identity:", {
        uid: fbUser.uid,
        email: fbUser.email,
        CashierID: initialUser.CashierID,
        legacyFound: Boolean(legacy),
        cacheFound: Boolean(cached),
      });

      // Kick off the background refresh (non-blocking).
      doRefreshProfile(fbUser, { legacy, cached });
    });

    return () => {
      disposed = true;
      unsubscribe();
    };
  }, [doRefreshProfile]);

  /* ---------- FIX #6: retry when connectivity returns ---------- */

  useEffect(() => {
    const handleOnline = () => {
      const fbUser = fbUserRef.current;
      if (!fbUser) return;

      console.info("[Auth] Network restored — refreshing profile");
      const rawLegacy = readLegacyUser();
      const legacy = legacyMatchesAuthUser(rawLegacy, fbUser)
        ? rawLegacy
        : null;
      const cached = readCache(fbUser.uid);

      refreshProfileRef.current?.(fbUser, { legacy, cached });
    };

    window.addEventListener("online", handleOnline);
    return () => window.removeEventListener("online", handleOnline);
  }, []);

  /* ---------- public actions ---------- */

  const login = useCallback(async (email, password) => {
    setError("");
    try {
      const credential = await signInWithEmailAndPassword(
        auth,
        email.trim(),
        password
      );
      return credential.user;
    } catch (loginError) {
      const message = friendly(loginError);
      setError(message);
      throw new Error(message);
    }
  }, []);

  const logout = useCallback(async () => {
    const uid = auth.currentUser?.uid;

    // Clear identity state so another account cannot inherit the
    // previous cashier's localStorage identity.
    clearLegacyUser();
    if (uid) clearCache(uid);

    activeUidRef.current = null;
    fbUserRef.current = null;
    userRef.current = null;
    setUser(null);
    setProfileLoading(false);
    setLoading(false);

    await signOut(auth);
  }, []);

  const value = useMemo(
    () => ({
      user,
      loading,
      profileLoading,
      error,
      login,
      logout,
      setError,
    }),
    [user, loading, profileLoading, error, login, logout]
  );

  return (
    <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
  );
}

/* ---------- friendly error messages ---------- */

function friendly(error) {
  switch (error?.code) {
    case "auth/invalid-credential":
    case "auth/wrong-password":
    case "auth/user-not-found":
      return "Wrong email or password.";
    case "auth/invalid-email":
      return "That email address is not valid.";
    case "auth/user-disabled":
      return "This account has been disabled.";
    case "auth/too-many-requests":
      return "Too many attempts. Please try again in a minute.";
    case "auth/network-request-failed":
      return "Network problem. Check your connection.";
    case "auth/operation-not-allowed":
      return "Email/Password sign-in is disabled in Firebase Console.";
    case "auth/invalid-api-key":
    case "auth/api-key-not-valid":
      return "Firebase config is missing or wrong (check .env).";
    default:
      return error?.message || "Login failed.";
  }
}