// src/pos/Dashboard.js
// ============================================================
// Product Catalogue — React + Firestore
// ------------------------------------------------------------
// Reads:
//   • ProductMaster        (all active products)
//   • ProductStockMaster   (stock + location price, filtered by
//                           the cashier's LocationID)
//   • Department           (filter sidebar — labelled "Supplier")
//   → merged client-side on ProductCode
//
// Cart lives in local state as `sections` — preserved exactly
// from the original (including the `qty: 1` fix on add).
//
// Preserves:
//   • Full permission gating (View / Sell / SellingPrice)
//   • Read-only banner when user cannot sell
//   • Price masking when user lacks CanViewSellingPrice
//   • Sidebar with collapse, search, cart badge
//   • Cart modal with ProductCode / Product / Discount / Qty / Price
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { Menu, X, Trash2, Lock } from "lucide-react";
import { useNavigate } from "react-router-dom";

import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import { listCollection } from "../lib/firestore";

const PRODUCT_MODULE = "Product";
const SALES_MODULE   = "Sale";

export default function Dashboard() {
  const navigate = useNavigate();
  const { user, logout } = useContext(AuthContext);

  // =====================================================
  // PERMISSIONS
  // =====================================================
  const { can, canField, loading: permissionsLoading } = usePermissions();

  const canViewProducts     = can(PRODUCT_MODULE, "View");
  const canSell             = can(SALES_MODULE, "Add");
  const canViewSellingPrice = canField(PRODUCT_MODULE, "SellingPrice");

  // =====================================================
  // STATE
  // =====================================================
  const [isOpen, setIsOpen] = useState(true);
  const [search, setSearch] = useState("");
  const [selectedDepartment, setSelectedDepartment] = useState("All");

  const [products, setProducts]         = useState([]);      // full catalogue for this location
  const [departments, setDepartments]   = useState([]);      // filter list
  const [sections, setSections]         = useState([]);      // cart
  const [cartOpen, setCartOpen]         = useState(false);
  const [loadingProducts, setLoadingProducts]     = useState(false);
  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [error, setError]               = useState("");

  // ------------------------------------------------------------
  // Location — same fallback chain as Catalog.jsx
  // ------------------------------------------------------------
  const locationID = Number(
    user?.LocationID ??
    user?.locationID ??
    user?.location   ??
    0
  );

  // =====================================================
  // LOAD PRODUCTS (ProductMaster × ProductStockMaster)
  // =====================================================
  const loadProducts = async () => {
    try {
      setLoadingProducts(true);
      setError("");

      if (!Number.isInteger(locationID) || locationID <= 0) {
        setError("Your account has no location assigned.");
        setProducts([]);
        return;
      }

      const masters = await listCollection("ProductMaster", {
        where: [["IsActive", "==", 1]],
      });

      const stockRows = await listCollection("ProductStockMaster", {
        where: [
          ["LocationID", "==", locationID],
          ["IsActive",   "==", 1],
        ],
      });

      const stockByCode = new Map();
      for (const s of stockRows) {
        const code = String(s.ProductCode || "").trim();
        if (code) stockByCode.set(code, s);
      }

      const merged = masters.map((p) => {
        const code = String(p.ProductCode || "").trim();
        const s    = stockByCode.get(code) || {};
        return {
          id:                     p.id,
          ProductCode:            p.ProductCode,
          ProductName:            p.ProductName,
          Department:             p.Department || "",
          BarCode:                p.BarCode    || "",
          Barcode:                p.Barcode    || p.BarCode || "",
          ProductImage:           p.ProductImage || p.imageUrl || "",
          FixedDiscountPercentage: Number(
                                    s.FixedDiscountPercentage ??
                                    p.FixedDiscountPercentage ?? 0
                                  ),
          Stock:                  Number(s.Stock ?? 0),
          StockCode:              s.StockCode || "",
          LocationID:             Number(s.LocationID ?? locationID),
          SellingPrice: Number(s.SellingPrice ?? p.SellingPrice ?? 0),
        };
      });

      setProducts(merged);
    } catch (err) {
      console.error("LOAD PRODUCTS ERROR:", err);
      setError(err?.message || "Unable to load products.");
      setProducts([]);
    } finally {
      setLoadingProducts(false);
    }
  };

  // =====================================================
  // LOAD DEPARTMENTS (filter sidebar)
  // =====================================================
  const loadDepartments = async () => {
    try {
      setLoadingDepartments(true);
      const rows = await listCollection("Department", {
        where: [["IsDelete", "==", 0]],
      });
      rows.sort((a, b) =>
        String(a.DepartmentName || "").localeCompare(String(b.DepartmentName || ""))
      );
      setDepartments(rows);
    } catch (err) {
      console.error("LOAD DEPARTMENTS ERROR:", err);
      setDepartments([]);
    } finally {
      setLoadingDepartments(false);
    }
  };

  // =====================================================
  // PAGE LOAD
  // =====================================================
  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewProducts) return;
    (async () => {
      await Promise.all([loadProducts(), loadDepartments()]);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewProducts, locationID]);

  // =====================================================
  // ADD SECTION TO CART
  // ------------------------------------------------------------
  // Same logic as the original — appends a new section, or
  // reuses the last empty section. qty is fixed at 1 (the
  // 🔧 FIX in your comments).
  // =====================================================
  const handleSelect = (product) => {
    if (!canSell) {
      alert("You do not have permission to add items to a sale.");
      return;
    }

    setSections((prev) => {
      const last = prev[prev.length - 1];

      if (!last || last.item) {
        return [
          ...prev,
          { id: (prev[prev.length - 1]?.id || 0) + 1, item: product, qty: 1 },
        ];
      }

      const updated = [...prev];
      updated[updated.length - 1] = {
        ...last,
        item: product,
        qty: 1,
      };
      return updated;
    });
  };

  const handleDelete = (id) => {
    if (!canSell) return;
    setSections((prev) => prev.filter((section) => section.id !== id));
  };

  const clearCart = () => {
    if (!canSell) return;
    setSections([]);
  };

  // =====================================================
  // FILTER
  // =====================================================
  const filteredProducts = useMemo(() => {
    const text = String(search || "").toLowerCase().trim();
    return (products ?? []).filter((product) => {
      const matchesSearch =
        !text || String(product?.ProductName ?? "").toLowerCase().includes(text);
      const matchesDepartment =
        selectedDepartment === "All" || product?.Department === selectedDepartment;
      return matchesSearch && matchesDepartment;
    });
  }, [products, search, selectedDepartment]);

  // =====================================================
  // CART BADGE
  // =====================================================
  const cartItemCount = useMemo(
    () => sections.reduce((total, s) => total + Number(s.qty || 0), 0),
    [sections]
  );

  // =====================================================
  // HELPERS
  // =====================================================
  const priceOrMask = (value) => (canViewSellingPrice ? value : "—");

  const getProductImage = (product) => {
    const PLACEHOLDER = "https://via.placeholder.com/400x300?text=No+Image";
    if (!product) return PLACEHOLDER;

    const img = product.ProductImage;
    if (!img) return PLACEHOLDER;
    if (typeof img === "string") return img;
    if (img.url && typeof img.url === "string") return img.url;
    if (img.data && Array.isArray(img.data)) {
      try {
        let binary = "";
        for (const byte of img.data) binary += String.fromCharCode(byte);
        return `data:image/jpeg;base64,${btoa(binary)}`;
      } catch (err) {
        console.error("IMAGE CONVERSION ERROR:", err);
      }
    }
    return PLACEHOLDER;
  };

  // =====================================================
  // LOGOUT
  // =====================================================
  const handleLogout = async () => {
    try {
      await logout();
    } catch (err) {
      console.error("LOGOUT ERROR:", err);
    }
    navigate("/POS/");
  };

  // =====================================================
  // ACCESS GATES
  // =====================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewProducts) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center p-6">
        <div className="max-w-xl w-full rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <Lock className="mx-auto text-red-500 mb-3" size={32} />
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view the product catalogue.
          </p>
          <button
            onClick={handleLogout}
            className="mt-6 rounded-lg bg-red-600 px-5 py-2 text-sm font-semibold text-white hover:bg-red-700"
          >
            Log out
          </button>
        </div>
      </div>
    );
  }

  // =====================================================
  // RENDER
  // =====================================================
  return (
    <div className="flex">
      {/* =================================================
          SIDEBAR
      ================================================= */}
      <div
        className={`bg-slate-800 text-white h-screen p-5 pt-8 relative duration-300 ${
          isOpen ? "w-64" : "w-20"
        }`}
      >
        <button
          className="absolute -right-3 top-9 bg-white text-black rounded-full p-1"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={18} /> : <Menu size={18} />}
        </button>

        <h1 className={`text-2xl font-bold mb-6 ${!isOpen && "hidden"}`}>MPOS</h1>

        <ul className="space-y-4">
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/home")}
          >
            Home
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/Dashboard")}
          >
            Catelog
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={() => navigate("/Settingss")}
          >
            Settings
          </li>
          <li
            className="hover:bg-slate-700 p-2 rounded cursor-pointer"
            onClick={handleLogout}
          >
            Logout
          </li>
        </ul>
      </div>

      {/* =================================================
          MAIN
      ================================================= */}
      <div className="flex-1 min-h-screen bg-gray-100">
        {/* Header */}
        <header className="bg-indigo-600 text-white shadow-md">
          <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
            <h1 className="text-2xl font-bold">Product Catalogue</h1>

            <input
              type="text"
              placeholder="Search products..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-72 px-4 py-2 rounded-lg text-black outline-none"
            />

            <button
              type="button"
              className="relative p-2 text-white hover:bg-indigo-500 rounded-full transition"
              onClick={() => setCartOpen(true)}
              aria-label="Shopping Cart"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                fill="none"
                viewBox="0 0 24 24"
                strokeWidth="2"
                stroke="currentColor"
                className="w-6 h-6"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-1 5h12m-9 0a1 1 0 100 2 1 1 0 000-2zm8 0a1 1 0 100 2 1 1 0 000-2"
                />
              </svg>
              {cartItemCount > 0 && (
                <span className="absolute top-0 right-0 transform translate-x-1/2 -translate-y-1/3 min-w-5 h-5 bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center px-1">
                  {cartItemCount}
                </span>
              )}
            </button>
          </div>
        </header>

        {/* Read-only banner */}
        {!canSell && (
          <div className="max-w-7xl mx-auto mt-4 flex items-center gap-2 rounded-lg border border-amber-200 bg-amber-50 px-4 py-2 text-sm text-amber-700">
            <Lock size={14} /> Read-only mode — you cannot add items to a sale.
          </div>
        )}

        {/* Error banner */}
        {error && (
          <div className="max-w-7xl mx-auto mt-4 rounded-lg border border-red-200 bg-red-50 px-4 py-2 text-sm text-red-700">
            {error}
          </div>
        )}

        {/* Main content */}
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row gap-6 p-6">
          {/* Sidebar — departments (labelled "Supplier" as in the original) */}
          <aside className="w-full md:w-64 bg-white rounded-xl shadow-md p-5">
            <h2 className="text-lg font-semibold mb-4">Supplier</h2>

            {loadingDepartments ? (
              <p className="text-gray-500 text-sm">Loading…</p>
            ) : (
              <div className="space-y-2">
                <button
                  onClick={() => setSelectedDepartment("All")}
                  className={`w-full text-left px-4 py-2 rounded-lg transition ${
                    selectedDepartment === "All"
                      ? "bg-indigo-600 text-white"
                      : "bg-gray-100 hover:bg-gray-200"
                  }`}
                >
                  All
                </button>

                {departments.map((department) => (
                  <button
                    key={department.id}
                    onClick={() => setSelectedDepartment(department.DepartmentName)}
                    className={`w-full text-left px-4 py-2 rounded-lg transition ${
                      selectedDepartment === department.DepartmentName
                        ? "bg-indigo-600 text-white"
                        : "bg-gray-100 hover:bg-gray-200"
                    }`}
                  >
                    {department.DepartmentName}
                  </button>
                ))}
              </div>
            )}
          </aside>

          {/* Products */}
          <main className="flex-1">
            <p className="mb-4 text-gray-600">
              Showing {products.length} products
            </p>

            {loadingProducts ? (
              <div className="bg-white p-10 rounded-xl shadow text-center text-gray-500">
                Loading products…
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.map((product) => (
                  <div
                    key={product.ProductCode || product.id}
                    className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition"
                  >
                    <img
                      src={getProductImage(product)}
                      alt={product.ProductName}
                      className="w-full h-56 object-cover"
                      onError={(e) => {
                        e.currentTarget.src =
                          "https://via.placeholder.com/400x300?text=No+Image";
                      }}
                    />

                    <div className="p-4">
                      <span className="text-xs bg-indigo-100 text-indigo-600 px-2 py-1 rounded">
                        {product.Department}
                      </span>

                      <h3 className="mt-3 text-lg font-semibold">
                        {product.ProductName}
                      </h3>

                      <div className="flex justify-between items-center mt-4">
                        <span className="text-xl font-bold text-indigo-600">
                          {priceOrMask(product.SellingPrice)}
                        </span>

                        {canSell ? (
                          <button
                            className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg"
                            onClick={() => handleSelect(product)}
                          >
                            Add Cart
                          </button>
                        ) : (
                          <span className="rounded-lg bg-slate-100 px-4 py-2 text-xs font-semibold text-slate-500">
                            Selling disabled
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {!loadingProducts && filteredProducts.length === 0 && (
              <div className="bg-white p-10 rounded-xl shadow text-center">
                <p className="text-gray-500">
                  No products found matching your search.
                </p>
              </div>
            )}
          </main>

          {/* =================================================
              CART MODAL
          ================================================= */}
          {cartOpen && (
            <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
              <div className="bg-white rounded-lg shadow-lg p-6 w-[32rem] max-w-full relative">
                <button
                  onClick={() => setCartOpen(false)}
                  className="absolute top-2 right-2 text-gray-500 hover:text-black"
                >
                  ✕
                </button>

                <h2 className="text-lg font-bold mb-4">Cart</h2>

                <ul className="divide-y">
                  <li className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 px-2 py-2 bg-gray-100 border-b text-xs font-semibold text-gray-600">
                    <span>ProductCode</span>
                    <span>Product</span>
                    <span>Discount</span>
                    <span>Qty</span>
                    <span>Price</span>
                  </li>
                </ul>

                {sections.length === 0 ? (
                  <p className="text-gray-400 text-center mt-10">
                    No items added
                  </p>
                ) : (
                  <ul className="divide-y">
                    {sections.map((section) => (
                      <li
                        key={section.id}
                        className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 items-center py-3 px-2 hover:bg-gray-100"
                      >
                        <span className="text-sm font-medium truncate">
                          {section.item.ProductCode}
                        </span>
                        <span className="text-sm font-medium truncate">
                          {section.item.ProductName}
                        </span>
                        <span className="text-sm font-medium">
                          {section.item.FixedDiscountPercentage ?? 0}%
                        </span>
                        <span className="text-sm font-medium">
                          {section.qty}
                        </span>
                        <span className="text-sm font-medium flex items-center justify-between">
                          <span>{priceOrMask(section.item.SellingPrice)}</span>

                          {canSell && (
                            <Trash2
                              size={16}
                              className="text-red-500 cursor-pointer hover:text-red-700"
                              onClick={() => handleDelete(section.id)}
                            />
                          )}
                        </span>
                      </li>
                    ))}
                  </ul>
                )}

                <div className="mt-6 flex justify-end gap-2">
                  <button
                    onClick={clearCart}
                    disabled={!canSell || sections.length === 0}
                    className="px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Clear
                  </button>

                  <button
                    onClick={() => setCartOpen(false)}
                    className="px-4 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300"
                  >
                    Close
                  </button>

                  {canSell && (
                    <button
                      onClick={() => setCartOpen(false)}
                      className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
                    >
                      Apply
                    </button>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}